const e={math:[{l:"الاستاتيكا - الوحدة 1 عزوم القوى",q:"عرّف عزم القوة حول نقطة في المستوى، واذكر وحدة قياسه وحالة انعدامه.",m:3,kp:[["عزم القوة ق حول نقطة أ = ق × ل، حيث ل طول العمود الساقط من أ على خط عمل القوة (ذراع العزم)",1],["ويُعبَّر عنه متجهياً: م = ر × ق (ر متجه موضع نقطة تأثير القوة بالنسبة لـ أ)، وهو عمودي على المستوى",1],["وحدته: نيوتن.متر (أو ث.كجم.متر ...). موجب إذا كان الدوران عكس عقارب الساعة وسالب في العكس",1],["ينعدم إذا كانت القوة معدومة أو مرّ خط عملها بالنقطة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الاستاتيكا - الوحدة 1",q:"اذكر نظرية فاريجنون (مبدأ العزوم) في القوى المستوية المتلاقية في نقطة.",m:3,kp:[["المجموع الجبري لعزوم عدة قوى مستوية تؤثر في نقطة، حول نقطة ما في مستواها، يساوي عزم محصلة هذه القوى حول النقطة نفسها",2],["خطوات الحل: أوجد المحصلة أو اكتب عزم كل قوة بإشارته، ثم طبّق المساواة وحدد المجهول",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الاستاتيكا - الوحدة 2 القوى المتوازية",q:"أوجد محصلة قوتين متوازيتين في اتجاه واحد (المقدار ونقطة التأثير).",m:3,kp:[["المحصلة ح = ق1 + ق2 وتوازيهما وفي اتجاههما",1],["نقطة تأثيرها ج تقع بين نقطتي التأثير أ، ب وتحقق: ق1 × أج = ق2 × جب (أي تقسم أب داخلياً بنسبة عكسية للقوتين)",2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الاستاتيكا - الوحدة 2",q:"كيف تحسب محصلة قوتين متوازيتين مختلفتين في الاتجاه وغير متساويتين؟",m:3,kp:[["ح = القوة الكبرى - القوة الصغرى وفي اتجاه الكبرى",1],["نقطة التأثير خارج القطعة أب من جهة القوة الكبرى وتحقق: ق1 × أج = ق2 × بج",2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الاستاتيكا - الوحدة 3 الازدواج",q:"عرّف الازدواج وعزمه، واذكر شرطي تكافؤ ازدواجين.",m:3,kp:[["الازدواج: قوتان متساويتان في المقدار، متوازيتان ومتضادتان في الاتجاه (ومحصلتهما صفر)، لا يجمعهما خط عمل واحد",1],["عزم الازدواج = إحدى القوتين × البعد العمودي بينهما، وهو ثابت حول أي نقطة في مستوى الازدواج",1],["يتكافأ ازدواجان مستويان إذا تساوى عزماهما جبرياً (المقدار والاتجاه)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الاستاتيكا - الوحدة 3",q:"ما شرط اتزان جسم متماسك تحت تأثير ازدواجين أو عدة ازدواجات مستوية؟",m:3,kp:[["يتزن الجسم إذا كان المجموع الجبري لعزوم الازدواجات يساوي صفراً",2],["محصلة عدة ازدواجات مستوية = ازدواج عزمه المجموع الجبري لعزومها",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الديناميكا - الوحدة 1 الحركة في خط مستقيم",q:"اكتب علاقات السرعة والعجلة بالتفاضل والتكامل للدوال المتجهة، وكيف تحصل على الإزاحة من السرعة.",m:3,kp:[["السرعة ع = د ر/د ن، والعجلة جـ = د ع/د ن = د²ر/د ن²",1],["بالعكس: ع = ∫ جـ د ن + ثابت ، ر = ∫ ع د ن + ثابت، ويُعيَّن الثابت من الشروط الابتدائية",2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الديناميكا - الوحدة 2",q:"اذكر قانون نيوتن الثاني في صورة كمية الحركة، وطبّقه على الجسم متغير الكتلة.",m:3,kp:[["القوة = المعدل الزمني لتغير كمية الحركة: ق = د(ك ع)/د ن",1],["للكتلة المتغيرة: ق = ك د ع/د ن + ع د ك/د ن",1],["للكتلة الثابتة: ق = ك ج (القانون المعتاد)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الديناميكا - الوحدة 2 الدفع",q:"عرّف دفع قوة، واذكر العلاقة بين الدفع وكمية الحركة.",m:3,kp:[["الدفع = القوة × زمن تأثيرها (للقوة الثابتة) = ∫ ق د ن للقوة المتغيرة، وهو كمية متجهة",1],["مبدأ الدفع وكمية الحركة: دفع القوة = التغير في كمية حركة الجسم: ق × ن = ك (ع2 - ع1)",2],["وحدته نيوتن.ثانية وتكافئ كجم.م/ث",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الديناميكا - الوحدة 3 الشغل",q:"عرّف الشغل الذي تبذله قوة ثابتة، وكيف يُحسب إذا تحرك الجسم بإزاحة؟",m:3,kp:[["الشغل كمية قياسية = حاصل الضرب القياسي لمتجه القوة في متجه الإزاحة: ش = ق · ف = ق ف جتا θ",2],["إذا كانت القوة متغيرة: ش = ∫ ق · د ر، وبوحدة الجول (نيوتن.متر)",1],["يكون الشغل صفراً إذا كانت القوة عمودية على الإزاحة، وسالباً إذا كانت ضد الحركة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الديناميكا - الوحدة 3 الطاقة",q:"اذكر مبدأ الشغل والطاقة وعبارتي طاقة الحركة وطاقة الوضع.",m:3,kp:[["طاقة الحركة = ½ ك ع²، وطاقة الوضع (للجاذبية) = ك ج ل (ل الارتفاع عن مستوى الصفر)",1],["مبدأ الشغل والطاقة: الشغل المبذول على الجسم = التغير في طاقة حركته (½ ك ع2² - ½ ك ع1²)",2],["حفظ الطاقة الميكانيكية: مجموع طاقتي الحركة والوضع ثابت إذا لم تؤثر قوة غير محافظة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الديناميكا - الوحدة 3 القدرة",q:"عرّف القدرة، واذكر قانونها بدلالة السرعة ووحداتها.",m:3,kp:[["القدرة = المعدل الزمني للشغل = د ش / د ن",1],["للقوة ق وسرعة ع: ق = ق · ع = ق ع جتا θ",1],["الوحدات: واط = جول/ثانية، وقوة الحصان = 746 واط (تقريباً؛ تحقق من الكتاب: ص126 مصطلح قوة الحصان)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"جبر 1-1 نظرية ذات الحدين",q:"اكتب مفكوك (س + أ)^ن واذكر الحد العام.",m:3,kp:[["(س + أ)^ن = مج من ر=0 إلى ن لـ ن_ر س^(ن−ر) أ^ر",1.5],["الحد العام (الحد رقم ر+1): ح(ر+1) = ن_ر س^(ن−ر) أ^ر",1],["عدد الحدود ن+1، ومجموع أسس س وأ في كل حد = ن، ومعاملات الحدود المتساوية البعد عن الطرفين متساوية",.5]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"جبر 1-2/1-3",q:"كيف تجد الحد المشتمل على س^ك والنسبة بين حدين متتاليين؟",m:3,kp:[["ضع الحد العام وساوِ أس س بالقيمة ك لتجد ر ثم عوّض (والحد الخالي من س عند أس س = صفر)",1.5],["النسبة بين الحدين: ح(ر+1) ÷ ح(ر) = [(ن − ر + 1) ÷ ر] × (أ ÷ س)",1.5]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"جبر 2-1 الأعداد المركبة",q:"اكتب الصورة المثلثية للعدد المركب ع = س + ص ت.",m:3,kp:[["المقياس |ع| = √(س² + ص²)",1],["السعة θ تحدد من tan θ = ص ÷ س مع مراعاة الربع الذي يقع فيه العدد",1],["ع = |ع| (جتا θ + ت جا θ)",1]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"جبر 2-2 نظرية ديموافر",q:"اذكر نظرية ديموافر واستخدامها في إيجاد قوة أو جذر عدد مركب.",m:3,kp:[["(جتا θ + ت جا θ)^ن = جتا ن θ + ت جا ن θ لكل ن صحيح",1.5],["لقوة ع^ن: |ع|^ن (جتا ن θ + ت جا ن θ)",.75],["للجذور النونية: |ع|^(1/ن) [جتا ((θ + 2π ك) ÷ ن) + ت جا ((θ + 2π ك) ÷ ن)]، ك = 0، 1، ... ن−1",.75]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"جبر 2-3 الجذور التكعيبية للواحد",q:"اذكر خواص الجذور التكعيبية للواحد الصحيح.",m:3,kp:[["الجذور: 1، ω، ω² حيث ω = −½ + (√3 ÷ 2) ت",1],["ω³ = 1",.75],["1 + ω + ω² = صفر",.75],["ω² = المرافق لـ ω وكل منهما مقلوب الآخر",.5]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"هندسة 3-3 ضرب المتجهات",q:"قارن بين الضرب القياسي والضرب الاتجاهي لمتجهين.",m:4,kp:[["القياسي: أ · ب = |أ||ب| جتا θ = أ1ب1 + أ2ب2 + أ3ب3، والناتج عدد، وينعدم إذا تعامد المتجهان",1.5],["الاتجاهي: أ × ب = |أ||ب| جا θ ن̂، والناتج متجه عمودي على المستوى الذي يضمهما، وينعدم إذا توازيا، ويحسب بالمحدد",1.5],["تطبيق: مساحة متوازي الأضلاع = |أ × ب|، ومساحة المثلث نصفها",1]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"هندسة 3-4 معادلة المستقيم",q:"اكتب معادلة المستقيم في الفراغ بصوره المختلفة.",m:3,kp:[["المتجهية: ر = ر0 + ك ع (ر0 متجه موضع نقطة عليه، ع متجه اتجاهه)",1],["البارامترية: س = س0 + ك ل، ص = ص0 + ك م، ع = ع0 + ك ن",1],["الكارتيزية: (س − س0) ÷ ل = (ص − ص0) ÷ م = (ع − ع0) ÷ ن",1]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"هندسة 3-5 معادلة المستوى",q:"اكتب معادلة المستوى بدلالة متجه عمودي عليه.",m:3,kp:[["إذا كان ن = (أ، ب، ج) عمودياً على المستوى ويمر بالنقطة (س0، ص0، ع0): أ(س − س0) + ب(ص − ص0) + ج(ع − ع0) = 0",1.5],["الصورة العامة أ س + ب ص + ج ع + د = 0",.75],["بعد نقطة عن المستوى = |أ س1 + ب ص1 + ج ع1 + د| ÷ √(أ² + ب² + ج²)",.75]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"تفاضل 1-1 الاشتقاق الضمني والبارامتري",q:"وضّح طريقة الاشتقاق الضمني والبارامتري.",m:3,kp:[["الضمني: اشتق طرفي المعادلة بالنسبة لـ س مع اعتبار ص دالة في س (قاعدة السلسلة د ص/د س) ثم حل لإيجاد د ص/د س",1.5],["البارامتري (س = د(ل)، ص = ر(ل)): د ص/د س = (د ص/د ل) ÷ (د س/د ل)، ثم د²ص/د س² = [د (د ص/د س)/د ل] ÷ (د س/د ل)",1.5]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"تفاضل 1-5 المعدلات الزمنية المرتبطة",q:"اذكر خطوات حل مسألة المعدلات الزمنية المرتبطة.",m:3,kp:[["ارسم الشكل ورمّز للكميات المتغيرة بدلالة الزمن ن",.75],["اكتب العلاقة بين الكميات واشتقها بالنسبة لـ ن بقاعدة السلسلة",1.25],["عوّض باللحظة المطلوبة وبالمعدلات المعلومة لتجد المعدل المجهول، مع مراعاة إشارة المعدل (تزايد +، تناقص −)",1]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"تفاضل 1-6/1-7 القيم العظمى والصغرى",q:"كيف تعيّن القيم القصوى للدالة ونقط الانعطاف؟",m:4,kp:[["نقط حرجة: د'(س) = 0 أو غير موجودة",1],["اختبار المشتقة الأولى: تغير إشارة د' من + إلى − عظمى محلية، ومن − إلى + صغرى محلية",1],["اختبار المشتقة الثانية: د''<0 عظمى، د''>0 صغرى",.5],["نقطة الانعطاف حيث د'' = 0 وتتغير إشارتها (تغير تقعر المنحنى)",.5]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"تفاضل 1-9 طرق التكامل",q:"اذكر طرق التكامل الرئيسية في الكتاب.",m:3,kp:[["التعويض: ∫ د(ر(س)) ر'(س) د س = ∫ د(ع) د ع",1],["بالتجزيء: ∫ ص د س = س ص − ∫ س د ص",1],["بالكسور الجزئية وتكامل الدوال الأسية واللوغاريتمية (∫ 1/س د س = ln|س| + ث ، ∫ هـ^س د س = هـ^س + ث)",1]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"تفاضل 1-10/1-11 التكامل المحدد",q:"اذكر النظرية الأساسية للتكامل وتطبيقه في حساب المساحة.",m:3,kp:[["∫ من أ إلى ب د(س) د س = ت(ب) − ت(أ) حيث ت دالة أصلية لـ د",1.5],["المساحة المحصورة بين منحنى د(س) ومحور السينات من أ إلى ب = ∫ |د(س)| د س (قسّم عند تغير الإشارة)",1.5]],lab:"من إعداد المنصة (قوانين وطرق قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"}],arabic:[{l:"النحو - الوحدة 3 النواسخ",q:"قارن بين كان وأخواتها وأفعال المقاربة والرجاء والشروع من حيث العمل والخبر، مع التمثيل.",m:3,kp:[["كان وأخواتها (كان، أمسى، أصبح، ظل، بات، صار، ليس، مازال، مادام) تدخل على الجملة الاسمية فترفع المبتدأ (اسمها) وتنصب الخبر (خبرها)، ويجوز تقديم الخبر على الاسم",1],["أفعال المقاربة: كاد، كرب، أوشك. الرجاء: عسى، حرى، اخلولق. الشروع: أخذ، شرع، طفق. وتعمل عمل كان",1],["خبرها جملة فعلية فعلها مضارع: مجرد من (أن) دائماً مع الشروع، ويكثر تجرده مع كاد وكرب، ويكثر اقترانه بها مع أوشك وعسى. مثال: كاد الليل ينتصف / عسى الله أن يأتي بالفرج",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 3 النواسخ",q:"متى تُكسر همزة (إنَّ) ومتى تُفتح؟ ما شروط عمل (لا) النافية للجنس؟",m:3,kp:[["تكسر في: أول الكلام، بعد ألا، بعد القول، في جواب القسم، في صدر جملة الصلة، في بدء جملة الحال. (مثال: قالوا: إن الحرب اندلعت)",1.2],["تفتح إذا أمكن تأويلها هي واسمها وخبرها بمصدر يعرب حسب موقعه: علمت أنك ناجح",.9],["لا النافية للجنس: يشترط أن يكون اسمها وخبرها نكرتين، واسمها متصلاً بها، وألا تسبق بحرف جر. مثال: لا طالبَ علمٍ فاشلٌ",.9]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 3 النواسخ",q:"أعرب: أوشكتِ الأزمةُ أن تنفرجَ.",m:2,kp:[["أوشكت: فعل ماضٍ ناقص من أفعال المقاربة مبني على الفتح، والتاء للتأنيث",.5],["الأزمةُ: اسم أوشك مرفوع وعلامة رفعه الضمة الظاهرة",.5],["أن: حرف مصدري ونصب. تنفرجَ: فعل مضارع منصوب بأن وعلامة نصبه الفتحة، والفاعل ضمير مستتر جوازاً تقديره هي",.5],["أن والفعل في تأويل مصدر في محل نصب خبر أوشك",.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 3 النواسخ",q:"أعرب: طفق النسيمُ يداعبُ الأغصانَ.",m:2,kp:[["طفق: فعل ماضٍ ناقص من أفعال الشروع مبني على الفتح",.5],["النسيمُ: اسم طفق مرفوع بالضمة",.5],["يداعبُ: فعل مضارع مرفوع بالضمة، والفاعل ضمير مستتر جوازاً تقديره هو، والجملة في محل نصب خبر طفق",.5],["الأغصانَ: مفعول به منصوب بالفتحة",.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 4 إعراب الاسم",q:"أعرب ما يأتي: (أ) حضر عمرو من المدرسة مبكراً مع عمر صديقه. (ب) لم أجد هنا عمراً لأنه سافر صباح اليوم.",m:4,kp:[["(أ) حضر: فعل ماضٍ مبني على الفتح. عمرٌو: فاعل مرفوع بالضمة الظاهرة (والواو زائدة للتفرقة بينه وبين عمر)",.8],["من المدرسة: جار ومجرور متعلقان بحضر. مبكراً: حال منصوب بالفتحة",.6],["مع: ظرف مكان منصوب بالفتحة وهو مضاف. عمرَ: مضاف إليه مجرور وعلامة جره الفتحة نيابة عن الكسرة لأنه ممنوع من الصرف (علم على وزن فُعَل). صديقه: بدل مجرور بالكسرة وهو مضاف والهاء مضاف إليه",.8],["(ب) لم: حرف نفي وجزم وقلب. أجد: فعل مضارع مجزوم بلم وعلامة جزمه السكون، والفاعل ضمير مستتر وجوباً تقديره أنا. هنا: ظرف مكان مبني في محل نصب",.8],["عمراً: مفعول به منصوب بالفتحة. لأنه: اللام حرف جر، أن حرف توكيد ونصب، والهاء ضمير مبني في محل نصب اسم أن",.5],["سافر: فعل ماضٍ والفاعل ضمير مستتر جوازاً تقديره هو والجملة في محل رفع خبر أن. صباحَ: ظرف زمان منصوب مضاف. اليومِ: مضاف إليه. (أن وما بعدها في تأويل مصدر مجرور باللام)",.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 4 إعراب الاسم",q:"(هذا إنسانٌ ساعٍ إلى الخير): أعرب الاسم المنقوص وعلل لحذف يائه. ثنِّ كلمة (قاضٍ) في: إننا بحاجة إلى قاضٍ يفهم روح القانون، وغيّر ما يلزم.",m:3,kp:[["ساعٍ: نعت مرفوع وعلامة رفعه الضمة المقدرة على الياء المحذوفة (منع من ظهورها الثقل)",1],["حذفت ياؤه لالتقاء الساكنين (الياء والتنوين) لأنه اسم منقوص نكرة مرفوع، وتبقى الكسرة دليلاً على الياء المحذوفة",1],["التثنية: قاضٍ → قاضيين (تعود الياء عند التثنية). إننا بحاجة إلى قاضيين يفهمان روح القانون",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 4 إعراب الاسم",q:"أعرب: (أ) تُوفِّيَ أبوه وهو صغير. (ب) جُنَّ الرجل من الفجيعة. ووضح الفرق بين: استُشهد على القاعدة بأبيات / استُشهد في ميدان القتال.",m:4,kp:[["توفّيَ: فعل ماضٍ مبني للمجهول مبني على الفتح المقدر للتعذر. أبوه: نائب فاعل مرفوع بالواو لأنه من الأسماء الخمسة وهو مضاف والهاء مضاف إليه",1],["وهو صغير: الواو واو الحال، هو ضمير منفصل مبتدأ، صغير خبر مرفوع، والجملة في محل نصب حال",1],["جُنَّ: فعل ماضٍ مبني للمجهول مبني على الفتح. الرجل: نائب فاعل مرفوع. من الفجيعة: جار ومجرور",1],["الفرق: (استشهدَ على القاعدة) مبني للمعلوم بمعنى استدل واستعان بشاهد؛ (استُشهِدَ في ميدان القتال) مبني للمجهول بمعنى قُتل شهيداً، والخطأ الشائع بناؤه للمعلوم",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 5 إعراب الفعل",q:"اذكر مواضع بناء الفعل الماضي والمضارع وما ينصب المضارع وما يجزمه، مع مثال.",m:4,kp:[["الماضي: يبنى على الفتح (كتب)، على الضم مع واو الجماعة (كتبوا)، على السكون مع ضمير رفع متحرك (كتبتُ)",1],["المضارع يبنى مع نون التوكيد على الفتح (ليكتبنَّ) ومع نون النسوة على السكون (يُرضعْنَ)",1],["نواصب المضارع: أن، لن، إذن، كي، حتى، لام التعليل، واو المعية، فاء السببية، لام الجحود",1],["جوازم المضارع: لم، لمّا، لام الأمر، لا الناهية، وأدوات الشرط الجازمة تجزم فعلين (فعل الشرط وجوابه)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 5 إعراب الفعل",q:"متى يُجزم المضارع في جواب الطلب؟ وما التقدير النحوي له؟ مثّل.",m:2,kp:[["يجزم إذا سبقه طلب (أمر أو نهي) وكان المضارع مترتباً على الطلب: زرني أزرْك / لا تدنُ من الأسد تسلمْ",1],["الجزم على تقدير شرط محذوف أداته (إنْ): إن تزرني أزرك، وإلا تدنُ من الأسد تسلمْ",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 6 الأدوات",q:"وضح الفرق بين كم الاستفهامية وكم الخبرية، وبيّن إعراب التمييز في كل منهما.",m:3,kp:[["كم الاستفهامية للسؤال، وتمييزها نكرة منصوب مفرد: كم كتاباً قرأت اليوم؟ (كتاباً: تمييز منصوب)",1.5],["كم الخبرية للإخبار عن الكثرة: كم من كتاب قرأته بدقة (تمييزها مجرور)",1.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 6 الأدوات",q:"ما حروف الجر الزائدة وشروط زيادة (من) و(الباء) و(الكاف)؟ مثّل.",m:3,kp:[["الزائدة ما يمكن الاستغناء عنه في الكلام، وأهمها من والباء والكاف",.8],["من: يسبقها نفي أو استفهام ويكون مجرورها نكرة: هل من خالق غير الله",.8],["الباء: تزاد في خبر ليس وفي فاعل كفى: كفى بالله وليًّا",.7],["الكاف: تزاد قبل كلمة (مثل): ليس كمثله شيء",.7]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النحو - الوحدة 6 الأدوات",q:"اذكر أنواع المنادى وحكم إعراب كل نوع مع مثال.",m:3,kp:[["المضاف منصوب: يا عبدَ الله. الشبيه بالمضاف منصوب: يا ساعياً في الخير",1],["النكرة المقصودة والعلم المفرد: مبنيان على ما يرفعان به: يا فتيانِ، يا منصفون، يا محمدُ",1],["المنادى المحلى بأل يُتوصل لندائه بـ (أيها) أو (أيتها) أو اسم الإشارة: يا أيها الطالبُ، يا هذا الفتى. ويجوز حذف أداة النداء: يوسفُ أعرض عن هذا",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"التعبير الوظيفي",q:"اكتب دعوة لحضور حفل تكريم المتفوقين بمدرستك.",m:5,kp:[["العنوان واضح (دعوة) ومخاطبة المدعو بأسلوب مهذب",1],["بيانات الحدث: المناسبة، اليوم والتاريخ، الوقت، المكان",2],["لغة رسمية سليمة وجمل قصيرة ثم عبارة شكر وتوقيع المرسل",1],["سلامة الإملاء والترقيم",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],biology:[{l:"الفصل 1 - الدعامة والحركة",q:"علل: حدوث إجهاد للعضلة الهيكلية.",m:2,kp:[["الانقباض المتتالي السريع يجعل الدم غير قادر على إيصال الأكسجين بالسرعة الكافية لاحتياجات العضلة",.6],["تحول العضلة الجليكوجين إلى جلوكوز يتأكسد بالتخمر اللاهوائي لإنتاج طاقة",.7],["يتراكم حمض اللاكتيك فيسبب تعب العضلة وإجهادها",.7]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 1 - الدعامة والحركة",q:"علل: يتواجد إنزيم الكولين استيريز في نقاط الاتصال العصبي العضلي.",m:2,kp:[["يحلل الأستيل كولين (الناقل العصبي) إلى كولين وحمض خليك",.8],["فيبطل مفعوله وتعود نفاذية غشاء الليفة العضلية لوضعها الطبيعي ويعود فرق الجهد",.7],["فتتهيأ العضلة للاستجابة لحفز جديد",.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 1 - الدعامة والحركة",q:"فسّر: تحدث الحركة نتيجة تآزر الأجهزة الهيكلي والعصبي والعضلي.",m:3,kp:[["الهيكلي: مكان اتصال العضلات ودعامة للأطراف والمفاصل تتيح الحركة",1],["العصبي: يعطي الأوامر على شكل سيالات عصبية تصل إلى العضلة فتنقبض أو تنبسط",1],["العضلي: ينقبض وينبسط فيحرك العظام فتتم الحركة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 1 - الدعامة والحركة",q:"اشرح آلية انقباض العضلة الهيكلية (نظرية الخيوط المنزلقة).",m:4,kp:[["وصول السيال العصبي يحرر الأستيل كولين في المشبك العصبي العضلي بمساعدة أيونات الكالسيوم، فيحدث لا استقطاب لغشاء الليفة",1],["الليفة من خيوط أكتين رفيعة وميوسين غليظة (هكسلي)",.8],["روابط مستعرضة من الميوسين تتصل بالأكتين بمساعدة Ca2+ و ATP",1],["الروابط تسحب خيوط الأكتين نحو بعضها فتتقارب خطوط Z وتنقبض العضلة",.8],["زوال المنبه تنفصل الروابط (تستهلك ATP) فتنبسط العضلة وتعود القطع العضلية لطولها",.4]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 2 - التنسيق الهرموني",q:"علل: يطلق على الغدة النخامية رئيسة الغدد الصماء.",m:2,kp:[["لأنها تتحكم في جهاز الغدد الصماء كله بهرموناتها (المايسترو)",.8],["هرموناتها تؤثر في إفراز معظم الغدد الصماء (مثل الدرقية والكظرية والمناسل)",.8],["وتتصل بتحت المهاد وتنظمها",.4]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 2 - التنسيق الهرموني",q:"علل: إصابة بعض الأفراد بالتضخم الجحوظي.",m:2,kp:[["زيادة إفراز الغدة الدرقية لهرمون الثيروكسين",.8],["يسبب تضخم الغدة وانتفاخ مقدمة الرقبة وجحوظ العينين",.6],["وزيادة أكسدة الغذاء ونقص الوزن وزيادة ضربات القلب",.6]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 2 - التنسيق الهرموني",q:"علل: البنكرياس غدة مزدوجة.",m:2,kp:[["غدة قنوية: تفرز إنزيمات هاضمة (خلايا حويصلية) تصب في الإثنى عشر عبر القناة البنكرياسية",1],["غدة صماء: جزر لانجرهانز تفرز الأنسولين (بيتا) والجلوكاجون (ألفا) في الدم مباشرة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 2 - التنسيق الهرموني",q:"علل: شعور مرضى السكر دائماً بالعطش.",m:2,kp:[["نقص الأنسولين يرفع الجلوكوز في الدم فيظهر في البول",.8],["خروج الجلوكوز يصاحبه إخراج كميات كبيرة من الماء (كثرة التبول) فيحدث العطش",1.2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 2 - التنسيق الهرموني",q:"علل: يستخدم خلاصة الفص الخلفي للغدة النخامية للماشية في الولادة المتعسرة.",m:2,kp:[["يحتوي على الهرمون المنبه لعضلات الرحم (الأوكسيتوسين)",1],["وهو يزيد تقلصات الرحم بشدة فيسرّع إخراج الجنين",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 2 - التنسيق الهرموني",q:"قارن بين دور الأنسولين والجلوكاجون في تنظيم سكر الدم.",m:3,kp:[["الأنسولين (خلايا بيتا) يخفض الجلوكوز: يسمح بدخوله للخلايا وأكسدته",1],["ويحول الجلوكوز إلى جليكوجين (كبد وعضلات) أو دهون",1],["الجلوكاجون (خلايا ألفا) يرفع الجلوكوز بتحويل جليكوجين الكبد إلى جلوكوز",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 2 - التنسيق الهرموني",q:"ما أمراض نقص إفراز الغدة الدرقية في الطفولة وفي البالغين؟",m:3,kp:[["نقص اليود يسبب التضخم البسيط (نقص الثيروكسين)",.8],["القماءة: نقص حاد في الطفولة: قصر قامة وتأخر عقلي وجنسي",1],["الميكسوديما: نقص حاد في البالغين: جفاف الجلد وتساقط الشعر وسمنة وبطء ضربات القلب وهبوط الأيض",1.2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 4 - المناعة",q:"اشرح خطوات المناعة الخلطية (بالأجسام المضادة).",m:4,kp:[["تتعرف الخلية البائية B على الأنتيجين وتدخله وتفككه وتعرضه مرتبطاً ببروتين MHC",.8],["الخلايا البلعمية الكبيرة تبتلع الممرض وتعرض الأنتيجين على سطحها",.8],["الخلية التائية المساعدة Th تتعرف عليه وتفرز إنترلوكينات تنشط الخلايا البائية",1],["الخلايا البائية تنقسم وتتمايز إلى خلايا ذاكرة وخلايا بلازمية تنتج الأجسام المضادة",.8],["الأجسام المضادة ترتبط بالأنتيجينات فتلتهمها البلعميات",.6]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 4 - المناعة",q:"اذكر أنواع الخلايا التائية ووظيفة كل منها.",m:3,kp:[["المساعدة Th: تنشط الخلايا التائية الأخرى والبائية لإنتاج الأجسام المضادة",1],["السامة Tc: تهاجم الخلايا السرطانية والأعضاء المزروعة والخلايا المصابة بالفيروس",1],["المثبطة Ts: تنظم الاستجابة وتكبحها بعد القضاء على الممرض",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 6 - تخليق البروتين",q:"وضح باختصار خطوات تكوين البروتين بدءاً من نسخ المعلومات الوراثية.",m:4,kp:[["النسخ: يُنسخ mRNA من أحد شريطي DNA، وتنسخ rRNA و tRNA من جيناتها",.8],["يبدأ التخليق بارتباط تحت وحدة الريبوسوم الصغيرة بـ mRNA عند كودون البدء AUG ويأتي tRNA حامل الميثيونين",1],["ترتبط تحت الوحدة الكبيرة ويدخل tRNA التالي بمضاد الكودون المناسب ويتكون رابطة ببتيدية",1],["يتحرك الريبوسوم على mRNA وتتكرر الدورة وتستطيل السلسلة",.6],["عند كودون الوقف يرتبط عامل الإطلاق فيتحرر عديد الببتيد وتنفصل تحت وحدتا الريبوسوم",.6]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 6 - تخليق البروتين",q:"ما المقصود بكل من: كودون البدء، كودون الوقف، مضاد الكودون، الشفرة الوراثية؟",m:4,kp:[["الشفرة الوراثية: تتابع النيوكليوتيدات في ثلاثيات على mRNA المنسوخة من DNA، تترجم إلى أحماض أمينية",1],["كودون البدء AUG يبدأ التخليق وهو للميثيونين",1],["كودونات الوقف (UAA, UAG, UGA) تعطي إشارة لانتهاء السلسلة",1],["مضاد الكودون: ثلاث قواعد على tRNA تتزاوج مع الكودون المناسب على mRNA",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 5 - الأحماض النووية",q:"قارن بين DNA وRNA من حيث السكر والقواعد النيتروجينية وعدد السلاسل.",m:3,kp:[["DNA: سكر ديوكسي ريبوز، قواعده A وG وC وT، وغالباً سلسلتان ملتفتان حلزونياً",1],["RNA: سكر ريبوز، قواعده A وG وC وU (اليوراسيل بدل الثايمين)، وغالباً سلسلة واحدة",1],["DNA يحمل المعلومات الوراثية، وRNA ينقلها ويشارك في تخليق البروتين",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 5 - الأحماض النووية",q:"اشرح قاعدة ازدواج القواعد النيتروجينية في جزيء DNA.",m:3,kp:[["A تتزاوج مع T برابطتين هيدروجينيتين",1],["G تتزاوج مع C بثلاث روابط هيدروجينية",1],["القاعدة البيورينية (كبيرة) تقابل بيريميدينية (صغيرة) فيثبت عرض الحلزون",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 5 - الأحماض النووية",q:"اشرح خطوات تضاعف DNA، وما الذي يضمن أن الجزيئين الناتجين متطابقان؟",m:3,kp:[["ينفك الحلزون وتنفصل السلسلتان بكسر الروابط الهيدروجينية بين القواعد",1],["تعمل كل سلسلة كقالب، وتضيف إنزيمات البلمرة نيوكليوتيدات مكملة لها حسب قاعدة الازدواج",1],["ينتج جزيئان كل منهما سلسلة قديمة وأخرى جديدة (تضاعف شبه محافظ)، فيتطابقان مع الأصل",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 5 - الأحماض النووية",q:"ما المقصود بالطفرة؟ اذكر مثالين لعوامل مسببة لها.",m:3,kp:[["الطفرة تغير مفاجئ في تتابع القواعد النيتروجينية في DNA أو في تركيب الكروموسومات",1],["قد تسبب تغيراً في البروتين الناتج أو لا تؤثر، وقد تورث إذا حدثت في الخلايا التناسلية",1],["من العوامل: الأشعة فوق البنفسجية وأشعة X وبعض المواد الكيميائية",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 5 - الأحماض النووية",q:"وضح مراحل تخليق البروتين في الخلية.",m:4,kp:[["النسخ: يتكون mRNA في النواة باستخدام إحدى سلسلتي DNA كقالب",1],["ينتقل mRNA إلى السيتوبلازم ويرتبط بالريبوسوم",1],["الترجمة: يحضر tRNA الأحماض الأمينية حسب الكودونات على mRNA فتتصل برابطة ببتيدية",1],["تتكون سلسلة عديد الببتيد وهي البروتين",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 6 - الوراثة والهندسة الوراثية",q:"اذكر نص قانون مندل الأول (قانون انعزال العوامل).",m:3,kp:[["كل صفة يتحكم فيها زوج من العوامل (الجينات) أحدهما من الأب والآخر من الأم",1],["عند تكوين الجاميتات ينفصل العاملان فيحمل كل جاميت عاملاً واحداً فقط",1],["عند الإخصاب يعود الزوج، وتظهر الصفة السائدة في الجيل الأول وتختفي المتنحية لتظهر في الجيل الثاني بنسبة 3 : 1",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 6 - الوراثة والهندسة الوراثية",q:"نبات بازلاء طويل متباين الزيجوت (Tt) لُقّح بنبات قصير (tt). ما الطرز الجينية والمظهرية المتوقعة ونسبها؟",m:3,kp:[["جاميتات الأول T وt، وجاميتات الثاني t فقط",1],["الطرز الجينية: 50% Tt و50% tt",1],["الطرز المظهرية: 50% طويل و50% قصير (نسبة 1 : 1)",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 6 - الوراثة والهندسة الوراثية",q:"ما الفرق بين السيادة التامة والسيادة غير التامة؟ مثّل بمثال للثانية.",m:3,kp:[["السيادة التامة: الصفة السائدة تخفي المتنحية في الهجين",1],["السيادة غير التامة: الهجين يظهر صفة وسطاً بين الأبوين",1],["مثال: تزهير نبات شب الليل: أحمر × أبيض ينتج وردي في الجيل الأول",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 6 - الوراثة والهندسة الوراثية",q:"وضح كيف يتحدد جنس المولود في الإنسان.",m:3,kp:[["الأنثى تحمل XX فتنتج بويضات كلها تحمل X",1],["الذكر يحمل XY فينتج حيوانات منوية نصفها X ونصفها Y",1],["إذا أخصب الحيوان المنوي X البويضة يولد أنثى، وإذا أخصبها Y يولد ذكر، فاحتمال كل منهما 50%",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 6 - الوراثة والهندسة الوراثية",q:"ما المقصود بالهندسة الوراثية؟ اذكر اثنين من تطبيقاتها.",m:3,kp:[["هي التحكم في المادة الوراثية بنقل جين من كائن إلى آخر لتغيير صفاته",1],["إنتاج الإنسولين البشري في البكتيريا لعلاج السكر",1],["إنتاج نباتات مقاومة للآفات أو تحمل الجفاف، أو إنتاج اللقاحات",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 3 - التكاثر في الكائنات الحية",q:"قارن بين التكاثر اللاجنسي والتكاثر الجنسي.",m:3,kp:[["اللاجنسي: كائن واحد، من غير جاميتات، والأبناء مطابقون وراثياً للأب",1],["الجنسي: يحتاج جاميتين (ذكرية وأنثوية) وإخصاب، والأبناء متنوعون وراثياً",1],["الجنسي يزيد التنوع والقدرة على التكيف، واللاجنسي أسرع وأبسط",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 3 - التكاثر في الكائنات الحية",q:"اذكر ثلاثة أنواع من التكاثر اللاجنسي مع مثال لكل نوع.",m:3,kp:[["الانشطار الثنائي: الأميبا والبكتيريا",1],["التبرعم: الخميرة والهيدرا",1],["التجدد أو التجزؤ: نجم البحر والإسفنج، والتكاثر الخضري في النبات مثل البطاطس",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 3 - التكاثر في الكائنات الحية",q:"اشرح تعاقب الأجيال في النباتات.",m:3,kp:[["يتعاقب جيل جاميتي (أحادي المجموعة الكروموسومية n) مع جيل بوغي (ثنائي 2n)",1],["الجيل البوغي ينتج أبواغاً بالانقسام الميوزي، والجيل الجاميتي ينتج جاميتات بالانقسام الميتوزي",1],["الإخصاب يعيد العدد 2n فيتكون الجيل البوغي من جديد",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 3 - التكاثر في الكائنات الحية",q:"ما أهمية الانقسام الميوزي في التكاثر الجنسي؟",m:3,kp:[["يختزل عدد الكروموسومات إلى النصف (من 2n إلى n) في الجاميتات",1],["بعد الإخصاب يعود العدد الأصلي 2n فيثبت عدد الكروموسومات في النوع",1],["العبور وتوزيع الكروموسومات يعطي تنوعاً وراثياً",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 3 - التكاثر في الكائنات الحية",q:"اذكر أجزاء الزهرة وما وظيفة كل جزء في التكاثر.",m:3,kp:[["الكأس والتويج: حماية الزهرة وجذب الحشرات",1],["الطلع (عضو التذكير): المتك ينتج حبوب اللقاح",1],["المتاع (عضو التأنيث): المبيض ينتج البويضات، والميسم يستقبل حبوب اللقاح",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 3 - التكاثر في الكائنات الحية",q:"اشرح عملية الإخصاب المزدوج في النباتات الزهرية.",m:3,kp:[["تنبت حبة اللقاح على الميسم وتكون أنبوبة لقاح تصل إلى البويضة",1],["أحد الأنويتين الذكريتين يخصب البويضة فيتكون الزيجوت (الجنين)",1],["النواة الذكرية الثانية تتحد مع النواتين القطبيتين فتتكون نسيج الإندوسبرم (الغذاء المخزن)",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 3 - التكاثر في الكائنات الحية",q:"وضح مراحل تكوين الحيوانات المنوية والبويضات.",m:3,kp:[["تكوين الحيوانات المنوية في الخصيتين بانقسام ميوزي، فينتج من الخلية الأم 4 حيوانات منوية",1],["تكوين البويضات في المبيضين بانقسام ميوزي، فينتج من الخلية الأم بويضة واحدة كبيرة وأجسام قطبية",1],["كل جاميت يحمل العدد الأحادي n من الكروموسومات (23 في الإنسان)",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"},{l:"الفصل 3 - التكاثر في الكائنات الحية",q:"اشرح ما يحدث من الإخصاب حتى انغراس الجنين في الإنسان.",m:3,kp:[["يحدث الإخصاب عادة في قناة فالوب فيتكون الزيجوت",1],["ينقسم الزيجوت ميتوزياً أثناء انتقاله نحو الرحم مكوناً كرة من الخلايا",1],["ينغرس الجنين في بطانة الرحم ويتغذى عن طريق المشيمة",1]],lab:"من إعداد المنصة، ليست إجابة رسمية من الوزارة"}],chemistry:[{l:"الباب الثاني - الكشف عن الأنيونات",q:"وضح بالمعادلات كيف تميز عملياً بين كبريتيت الصوديوم وكبريتات الصوديوم.",m:2,kp:[["إضافة حمض HCl المخفف: الكبريتيت يتصاعد SO2 نفاذ الرائحة يخضّر ورقة مبللة بثاني كرومات البوتاسيوم المحمضة؛ الكبريتات لا تتفاعل",.8],["Na2SO3 + 2HCl → 2NaCl + H2O + SO2↑",.6],["أو كاشف BaCl2: الكبريتات راسب أبيض BaSO4 لا يذوب في HCl المخفف: Na2SO4 + BaCl2 → BaSO4↓ + 2NaCl",.6]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - الكشف عن الكاتيونات",q:"وضح بالمعادلات كيف تميز بين كلوريد الحديد (II) وكلوريد الحديد (III).",m:2,kp:[["إضافة NaOH: FeCl2 يعطي راسباً أبيض مخضراً يتحول إلى بني محمر بالتعرض للهواء",.7],["FeCl2 + 2NaOH → Fe(OH)2↓ + 2NaCl",.5],["FeCl3 يعطي راسباً بنياً محمراً جيلاتينياً: FeCl3 + 3NaOH → Fe(OH)3↓ + 3NaCl",.8]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - الكشف عن الأنيونات",q:"وضح بالمعادلات كيف تميز بين نيتريت الصوديوم ونيترات الصوديوم.",m:2,kp:[["HCl المخفف: النيتريت يعطي NO عديم اللون يتحول عند فوهة الأنبوبة إلى NO2 بني محمر؛ النيترات لا تتفاعل",.8],["2NaNO2 + 2HCl → 2NaCl + H2O + NO↑ + NO2↑",.5],["أو برمنجنات البوتاسيوم المحمضة: النيتريت يزيل اللون البنفسجي، النيترات لا تزيله",.4],["النيترات: اختبار الحلقة البنية (FeSO4 + H2SO4 المركز)",.3]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - الكشف عن الكاتيونات",q:"وضح بالمعادلات كيف تميز بين كلوريد الصوديوم وكلوريد الألومنيوم.",m:2,kp:[["إضافة NaOH بالتدريج: AlCl3 يعطي راسباً أبيض جيلاتينياً",.6],["AlCl3 + 3NaOH → Al(OH)3↓ + 3NaCl",.5],["الراسب يذوب في زيادة NaOH لأنه متردد: Al(OH)3 + NaOH → NaAlO2 + 2H2O",.6],["NaCl لا يعطي راسباً",.3]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - تعيين الشق",q:"اذكر اسم وصيغة الشق الذي أعطى: (أ) راسباً أبيض مخضراً مع NaOH (ب) راسباً أبيض بعد التسخين مع MgSO4 (ج) راسباً أصفر مع AgNO3 لا يذوب في النشادر.",m:3,kp:[["(أ) أيون الحديد (II) Fe2+",1],["(ب) البيكربونات HCO3-",1],["(ج) اليوديد I-",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - تعليل",q:"علل: (أ) لا يصلح HCl المخفف للتمييز بين كربونات وبيكربونات الصوديوم (ب) يزول لون برمنجنات البوتاسيوم المحمضة عند إضافة نيتريت البوتاسيوم (ج) تسود ورقة مبللة بأسيتات الرصاص (II) بغاز H2S (د) تتصاعد أبخرة بنفسجية عند تفاعل H2SO4 المركز مع KI.",m:4,kp:[["(أ) كلاهما يعطي CO2 يعكر ماء الجير؛ للتمييز نستخدم MgSO4: الكربونات راسب أبيض على البارد والبيكربونات بعد التسخين",1],["(ب) النيتريت مختزل يختزل MnO4- البنفسجي إلى Mn2+ عديم اللون ويتأكسد إلى نيترات",1],["(ج) يتكون كبريتيد الرصاص (II) PbS الأسود: H2S + (CH3COO)2Pb → PbS↓ + 2CH3COOH",1],["(د) H2SO4 المركز يطرد HI الذي يتأكسد جزئياً فيتصاعد اليود بخاراً بنفسجياً: 2KI + 2H2SO4 → K2SO4 + SO2 + I2 + 2H2O (أو 2HI + H2SO4 → I2 + SO2 + 2H2O)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - تعيين الأنيونات والكاتيونات",q:"أضيف NaOH إلى محاليل ثلاثة كلوريدات: الأول راسب أبيض جيلاتيني، الثاني راسب بني محمر، الثالث راسب أبيض مخضر. اذكر الشق القاعدي لكل ملح واكتب المعادلات.",m:3,kp:[["الأول: Al3+ ؛ AlCl3 + 3NaOH → Al(OH)3↓ + 3NaCl",1],["الثاني: Fe3+ ؛ FeCl3 + 3NaOH → Fe(OH)3↓ + 3NaCl",1],["الثالث: Fe2+ ؛ FeCl2 + 2NaOH → Fe(OH)2↓ + 2NaCl",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - تعيين الأنيونات",q:"أضيف HCl المخفف إلى ثلاثة أملاح صوديوم صلبة: الأول يتصاعد غاز نفاذ الرائحة يخضّر ورقة مبللة بثاني كرومات البوتاسيوم المحمضة؛ الثاني غاز عديم اللون يتحول عند الفوهة إلى بني محمر؛ الثالث غاز عديم اللون نفاذ الرائحة مع مادة صفراء. اذكر الشق الحمضي واكتب المعادلات.",m:3,kp:[["الأول: الكبريتيت SO3(2-): Na2SO3 + 2HCl → 2NaCl + H2O + SO2↑",1],["الثاني: النيتريت NO2-: 2NaNO2 + 2HCl → 2NaCl + H2O + NO↑ + NO2↑",1],["الثالث: الثيوكبريتات S2O3(2-): Na2S2O3 + 2HCl → 2NaCl + H2O + SO2↑ + S↓",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - حمض الهيدروكلوريك المخفف",q:"وضح بالمعادلات تأثير HCl المخفف على أملاح الكربونات والكبريتيت والثيوكبريتات والكبريتيد، مع ذكر الكاشف المناسب لكل غاز.",m:4,kp:[["كربونات: Na2CO3 + 2HCl → 2NaCl + H2O + CO2↑ ؛ يعكر ماء الجير",1],["كبريتيت: Na2SO3 + 2HCl → 2NaCl + H2O + SO2↑ ؛ يخضّر ورقة ثاني كرومات محمضة",1],["ثيوكبريتات: Na2S2O3 + 2HCl → 2NaCl + H2O + SO2↑ + S↓ (عكارة صفراء)",1],["كبريتيد: Na2S + 2HCl → 2NaCl + H2S↑ ؛ يسوّد ورقة أسيتات الرصاص (II)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - حمض الكبريتيك المركز",q:"ما تأثير H2SO4 المركز على الأنيونات: الكلوريد والبروميد واليوديد والنيترات؟",m:4,kp:[["الكلوريد: يتصاعد HCl عديم اللون يكوّن سحباً بيضاء مع ساق مبللة بالنشادر",1],["البروميد: يتصاعد HBr ويتأكسد جزئياً فتنفصل أبخرة برتقالية حمراء من Br2",1],["اليوديد: يتصاعد HI ويتأكسد جزئياً فتنفصل أبخرة بنفسجية من I2 تزرق ورقة النشا",1],["النيترات: أبخرة بنية من NO2 وتزداد بإضافة خراطة النحاس",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثاني - التحليل الكمي (حجمي)",q:"سخن 6.72 جم من بيكربونات الصوديوم حتى تمام التحلل، وأذيب الناتج في الماء وأكمل إلى 400 مل. تعادل 50 مل منه مع 30 مل من HCl المخفف. احسب: (1) تركيز كربونات الصوديوم (2) مولارية HCl. (Na=23, O=16, C=12, H=1)",m:4,kp:[["2NaHCO3 → Na2CO3 + H2O + CO2 ؛ كتلة المول NaHCO3 = 84 جم",.6],["مولات NaHCO3 = 6.72/84 = 0.08 mol ⟹ Na2CO3 = 0.04 mol",.8],["تركيز Na2CO3 = 0.04/0.4 = 0.1 M",.8],["Na2CO3 + 2HCl → 2NaCl + H2O + CO2 ؛ مولات Na2CO3 في 50 مل = 0.1×0.05 = 0.005 mol",.7],["مولات HCl = 0.01 mol في 30 مل ⟹ M = 0.01/0.030 ≈ 0.333 M",1.1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثالث - الاتزان الأيوني",q:"وضح سبب: (أ) غاز HCl في الماء يوصل التيار وفي البنزين لا يوصل (ب) صعوبة انحلال HCl إلى عنصريه علماً بأن Kc للتكوين = 4.4×10^12 (ج) ماذا يحدث لتركيز أيون الأسيتات عند إضافة HCl إلى حمض الخليك.",m:3,kp:[["(أ) في الماء يتأين HCl ويعطي أيونات حرة الحركة (H3O+ و Cl-) فيوصل؛ في البنزين يبقى جزيئات غير متأينة",1],["(ب) Kc كبيرة جداً ⟹ الاتزان يميل بشدة نحو النواتج (HCl) فلا ينحل إلا في أقل القليل",1],["(ج) زيادة [H3O+] تزيح الاتزان CH3COOH ⇌ CH3COO- + H3O+ ناحية اليسار (لوشاتيليه) فيقل تركيز الأسيتات",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الثالث - قانون استفالد للتخفيف",q:"وضح بالتجربة أثر التخفيف على كل من حمض الهيدروكلوريك وحمض الخليك. فسر ذلك.",m:3,kp:[["حمض الخليك ضعيف: بالتخفيف تزداد درجة التأين α (Ka = α²C ثابتة، α ∝ 1/√C)",1],["HCl قوي: متأين تقريباً كلياً قبل وبعد التخفيف فلا تزيد α عملياً (تقل [H+] فقط بالتخفيف)",1],["التجربة: دائرة بها مصباح ومحلولان بنفس التركيز ثم التخفيف؛ يبقى توهج HCl أكبر من الخليك (أو قياس pH)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الأول - العناصر الانتقالية",q:"فسر: سهولة أكسدة أيون الحديد (II) إلى الحديد (III) وصعوبة ذلك في أيون المنجنيز (II).",m:2,kp:[["Fe2+ : [Ar] 3d6 ويتحول إلى Fe3+ : 3d5 نصف ممتلئ أكثر استقراراً",.8],["Mn2+ : [Ar] 3d5 نصف ممتلئ بالفعل فهو مستقر ويحتاج طاقة كبيرة لإزالة إلكترون آخر",.8],["لذلك يتأكسد Fe2+ بسهولة بينما يصعب أكسدة Mn2+",.4]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الأول - العناصر الانتقالية",q:"وضح العلاقة بين الخاصية المغناطيسية والتركيب الإلكتروني: قارن بين Fe3+ و Zn2+.",m:2,kp:[["Fe3+ : 3d5 خمسة إلكترونات مفردة ⟹ بارامغناطيسي",.7],["Zn2+ : 3d10 كل الإلكترونات مزدوجة ⟹ ديامغناطيسي",.7],["المادة البارامغناطيسية تنجذب للمجال وقوة الجذب تتناسب مع عدد الإلكترونات المفردة",.6]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الرابع - الكيمياء الكهربية",q:"احسب القوة الدافعة الكهربية لخلية دانيال (Zn/Cu) علماً بأن جهد الاختزال القياسي: Cu = +0.34 V ، Zn = -0.76 V واكتب تفاعلي القطبين.",m:3,kp:[["الأنود (أكسدة): Zn → Zn2+ + 2e-",.8],["الكاثود (اختزال): Cu2+ + 2e- → Cu",.8],["emf = جهد اختزال الكاثود - جهد اختزال الأنود = 0.34 - (-0.76) = 1.10 V",1.4]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب الخامس - الكيمياء العضوية",q:"وضح كيف يحضّر الإيثانول من الإيثين بالهيدرة الحفزية، ولماذا يضاف H2SO4 المركز.",m:3,kp:[["الماء إلكتروليت ضعيف وتركيز H+ فيه لا يكفي لكسر الرابطة المزدوجة فيضاف الحمض لتوفير H+",1],["إضافة H2SO4 المركز: CH2=CH2 + H2SO4 → CH3CH2HSO4 (كبريتات إيثيل هيدروجينية)",1],["التحلل المائي: CH3CH2HSO4 + H2O → CH3CH2OH + H2SO4",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],english2:[{l:"Unit 1 Learning & Ambition - Writing",q:"Write a short paragraph of (6-8 sentences) about a school project you are working on right now. Explain: 1. What are you studying or making? 2. What are you and your classmates doing right now? 3. How does teamwork help you achieve better results?",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["ما المشروع بالمضارع المستمر (we are making a model of ...)",1],["ما يفعله الزملاء الآن (Ali is drawing, we are working together)",1],["فائدة العمل الجماعي (teamwork helps us share ideas and finish faster)",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 1 - Social media post",q:"Write a social media post of (6-8) sentences about your study habits and your goals for next year. Guiding elements: My Habit - My main goal - My Future Ambition - Challenge - Teamwork.",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["My Habit: عادة دراسية (I study two hours every day)",1],["My main goal: هدف السنة القادمة",1],["My Future Ambition: الطموح (I want to become a ...)",1],["Challenge: تحدٍّ وكيف أتغلب عليه",1],["Teamwork: دور الزملاء أو الفريق",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 1 - Writing 3",q:"Write a paragraph of (6-8) sentences about 'My Goals for the Future'.",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["الهدف الدراسي (university, major)",1],["الهدف المهني",1],["كيف سأحققه (study hard, practice every day)",1],["تحدٍّ محتمل أو مهارة سأتعلمها",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 2 Sports & Community - Writing",q:"Write a paragraph of (6-8) sentences about 'your favorite athlete'. Guiding elements: Name - Sport - Skills - Achievements.",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["Name: الاسم والجنسية",1],["Sport: الرياضة",1],["Skills: مهاراته (fast, strong, skilful)",1],["Achievements: إنجازاته (won medals)",1],["لماذا أحبه",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 2 - Community participation",q:"Write a paragraph of (6-8) sentences about 'Community participation'. Guiding elements: I can help my community... We clean... Helping others makes...",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["I can help my community by ... (نشاطان أو ثلاثة)",1],["We clean the streets / plant trees",1],["Helping others makes us ... (feel happy, proud)",1],["أهمية العمل التطوعي",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 2 - My Sports Hero",q:"Write a paragraph of (6-8) sentences about 'My Sports Hero'.",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["من البطل ولماذا هو قدوة",1],["صفاته (hard-working, honest)",1],["ما أنجزه",1],["ماذا أتعلم منه",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 3 Jobs & Technology - Writing",q:"Write a paragraph of (6-8) sentences about 'Your Dream Job'. Guiding elements: job - help - people - work.",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["job: الوظيفة (doctor, engineer, teacher)",1],["help: كيف تساعد الناس",1],["work: ما يقوم به في عمله",1],["لماذا أريدها وما أحتاجه (study, practice)",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 3 - Blog post",q:"Write a blog post of (6-8) sentences about 'How Technology Helps People'. Guiding elements: use technology - help people - learn new things - communicate online.",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["use technology: أمثلة (phones, computers)",1],["help people: الطب والعمل",1],["learn new things: التعلم عبر الإنترنت",1],["communicate online: التواصل مع الأهل",1],["الاستخدام الآمن",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 3 - Working in a Team",q:"Write a paragraph of (6-8) sentences about 'Working in a Team'.",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["معنى العمل الجماعي",1],["فوائده (share ideas, finish faster, learn from others)",1],["مثال من المدرسة أو العمل",1],["كيف أكون عضواً جيداً (listen, respect, help)",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Review - Writing choice",q:"Write a paragraph of 6-8 sentences on one of the following topics: 1. My Future Job and How I Will Succeed (ambition - goal - technology - challenge) 2. The Importance of Teamwork in Our Community (volunteer - help - responsibility).",m:3,kp:[["Opening sentence: يذكر الموضوع بوضوح",1],["استخدام الكلمات الإرشادية المعطاة كلها",1],["فقرة منظمة: فكرة رئيسية ثم تفاصيل ثم خاتمة",1],["Closing sentence: جملة ختام مناسبة",1],["6-8 جمل، قواعد صحيحة، إملاء وترقيم، وروابط بسيطة (and, because, also)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 1 Grammar - Present continuous (error correction)",q:"Correct the mistake: 'He am working very hard this week.'",m:2,kp:[["He is working very hard this week.",1],["المضارع المستمر: am مع I، is مع he/she/it، are مع we/you/they + verb-ing",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],english:[{l:"Unit 1 Inside the World of Care - Writing",q:"Write a short essay of (180-200) words about 3 activities you do every morning.",m:3,kp:[["Introduction: يعرّف الموضوع ويذكر الفكرة الرئيسية (thesis) في جملة أو اثنتين",1],["Body: ثلاث فقرات، كل فقرة نشاط (waking up and exercising / having breakfast / preparing for school) مع تفاصيل",2],["روابط الترتيب: First, Then, After that, Finally وظروف التكرار",1],["Conclusion: يلخّص الأفكار ويعيد الرأي بكلمات مختلفة",1],["الطول 180-200 كلمة، روابط (First, In addition, However, In conclusion)، لغة وإملاء وترقيم سليم",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 1 - Blog post",q:"Write a blog post about a personal experience (a trip): introduction, main body (2-4 paragraphs), conclusion.",m:3,kp:[["Title جذاب + Introduction (1-2 فقرة): ماذا حدث ومتى وأين",1],["Main Body (2-4 فقرات): كل فقرة محور (Food / Culture ...) بجمل وصفية ومشاعر",2],["Conclusion: ما تعلمته وتوصية للقارئ",1],["أسلوب شخصي بضمير المتكلم وزمن الماضي وروابط مناسبة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 2 The Power of Machines - Process description",q:"Choose a familiar machine/device and write about (180-200) words describing how it works (process description).",m:3,kp:[["Introduction: ما الآلة وما غرضها",1],["Main steps: خطوات التشغيل بترتيب (First, Next, After that, Then, Finally) وصيغة المبني للمجهول (is turned on, is heated)",2],["Conclusion: فائدتها وأهميتها",1],["180-200 كلمة ولغة سليمة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 2 - Argumentative essay",q:"Write an argumentative essay (180-200 words) on whether students should use phones in class.",m:3,kp:[["Introduction: خلفية + claim (I believe that...)",1],["Body 1: السبب الأول بمثال أو دليل (Firstly)",1],["Body 2: السبب الثاني (Secondly / In addition)",1],["Opposing view: الرأي المعاكس والرد عليه (On the other hand... However)",1],["Conclusion: إعادة الرأي وتلخيص (In conclusion)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 3 Protect Nature, Protect Future - Descriptive essay",q:"Write a descriptive essay of (180-200) words on what could happen if countries didn't take urgent precautions to solve climate problems.",m:3,kp:[["Introduction: يعرّف الموضوع ويذكر الفكرة الرئيسية (thesis) في جملة أو اثنتين",1],["Body: ثلاث نتائج محتملة (ارتفاع الحرارة وذوبان الجليد / فيضانات وجفاف / فقدان الحياة البرية ونقص الغذاء) مع modals للاحتمال (could, might, would)",2],["وصف حسي وأمثلة واقعية",1],["Conclusion: يلخّص الأفكار ويعيد الرأي بكلمات مختلفة",1],["الطول 180-200 كلمة، روابط (First, In addition, However, In conclusion)، لغة وإملاء وترقيم سليم",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 3 - Persuasive essay",q:"Write a persuasive essay (180-200 words) on 'Small Actions, Big Impact'.",m:3,kp:[["Introduction: يعرّف الموضوع ويذكر الفكرة الرئيسية (thesis) في جملة أو اثنتين",1],["Body 1: فعل صغير (توفير الماء والكهرباء، إعادة التدوير) وأثره",1],["Body 2: فعل آخر (تقليل البلاستيك، زراعة الأشجار) وأثره على المجتمع",1],["أدوات الإقناع: أسئلة بلاغية، أرقام، أوامر (Let's..., We must...)",1],["Conclusion: يلخّص الأفكار ويعيد الرأي بكلمات مختلفة",1],["الطول 180-200 كلمة، روابط (First, In addition, However, In conclusion)، لغة وإملاء وترقيم سليم",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 4 Marine Life - Short story",q:"Write a short story about your adventure in the sea.",m:3,kp:[["Setting & characters: المكان والزمان والشخصيات",1],["Plot: بداية - مشكلة - ذروة - حل بالماضي البسيط والمستمر",2],["Descriptive language: صفات ومركبات صفات (crystal-clear water, colourful coral)",1],["Ending: نهاية ودرس، 180-200 كلمة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 6 Let's Hang Out! - Opinion essay",q:"Write an essay of about 180 to 200 words on 'How important it is for an individual to be sociable'. Make use of the vocabulary in the text.",m:3,kp:[["Introduction: يعرّف الموضوع ويذكر الفكرة الرئيسية (thesis) في جملة أو اثنتين",1],["Body 1: فوائد الاجتماعية (friends, support, communication skills)",1],["Body 2: مثال واقعي أو الجانب الآخر (privacy, shyness)",1],["استعمال مفردات النص المقرر",1],["Conclusion: يلخّص الأفكار ويعيد الرأي بكلمات مختلفة",1],["الطول 180-200 كلمة، روابط (First, In addition, However, In conclusion)، لغة وإملاء وترقيم سليم",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 7 At The Airport - For/against essay",q:"Write a for/against essay of (180-200) words about 'Social media's impact'.",m:3,kp:[["Introduction: للقضية وجهان",1],["Advantages: نقطتان بأمثلة (تواصل، تعلم، أخبار)",1],["Disadvantages: نقطتان بأمثلة (إدمان، خصوصية، أخبار كاذبة)",1],["Conclusion: رأي متوازن",1],["روابط: On the one hand, On the other hand, However, Moreover",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unit 7 - Expository essay",q:"Write an expository essay of (180-200) words about ways to stay safe while traveling.",m:3,kp:[["Introduction: يعرّف الموضوع ويذكر الفكرة الرئيسية (thesis) في جملة أو اثنتين",1],["Body: ثلاث طرق (keep documents safe / follow airport instructions / avoid sharing personal information)",2],["روابط الترتيب والإضافة المذكورة في الكتاب (first, next, after that, also, in addition)",1],["Conclusion: يلخّص الأفكار ويعيد الرأي بكلمات مختلفة",1],["الطول 180-200 كلمة، روابط (First, In addition, However, In conclusion)، لغة وإملاء وترقيم سليم",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Grammar - Reported speech (Rewrite)",q:"Rewrite using reported speech: 'I am studying for my exams now,' said Ali.",m:3,kp:[["Ali said (that) he was studying for his exams then.",2],["تغيير الضمير (I→he) والزمن (am studying→was studying) والظرف (now→then) وحذف علامات الاقتباس",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Grammar - Present perfect passive (Rewrite)",q:"Rewrite: 'The students haven't written their essays yet.' (Start: Their essays ...)",m:3,kp:[["Their essays haven't been written (by the students) yet.",2],["المبني للمجهول في المضارع التام: have/has + not + been + past participle",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Grammar - Modals of deduction / regret (Rewrite)",q:"Rewrite: 'Perhaps he forgot the key at home.' (He might ...) and 'I regret not studying harder.' (I should ...)",m:3,kp:[["He might have forgotten the key at home.",1],["I should have studied harder.",1],["البنية: modal + have + past participle للاستنتاج في الماضي (must/might/can't have) وللندم واللوم (should/shouldn't have)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Translation",q:"Translate into English: يجب أن نحافظ على البيئة لأن الأعمال الصغيرة تصنع فرقاً كبيراً.",m:3,kp:[["We must protect the environment because small actions make a big difference.",2],["الدقة في الزمن والمفردات والترتيب وعدم الترجمة الحرفية",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],geography:[{l:"الوحدة 1 الدرس 1 الدولة",q:"قارن بين الدولة الفيدرالية والدولة الكونفدرالية من حيث أهم خصائص كل منهما.",m:4,kp:[["الفيدرالية: دستور واحد، وتقسم السلطات بين سلطة مركزية (السياسة الخارجية والاقتصاد والدفاع والأمن) وسلطات محلية تدير شئون السكان، وتحقق توازناً بينهما، ولا يمكن أن تتحول إلى كونفدرالية",2],["الكونفدرالية: اتحاد بمعاهدة، لكل دولة دستورها وعلمها وتمثيلها المستقل ووظائفها السيادية وعاصمتها، وقد يكون لها عملة واحدة كاليورو (الاتحاد الأوروبي)",2],["يمكن أن تتحول الكونفدرالية إلى فيدرالية (سويسرا)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 الدرس 1",q:"بم تفسر: الدولة الكونفدرالية أقل أنواع الدول شيوعاً وأكثرها هشاشة؟",m:3,kp:[["لأن كل دولة في الاتحاد تحتفظ بسيادتها وشخصيتها القانونية",1],["ولأنه يحق لأي دولة أن تنفصل عن الاتحاد في أي وقت تشاء",2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 الدرس 1",q:"بم تفسر: تحاول الدولة أن تكون عاصمتها محصنة وبعيدة عن الحدود؟ (وما عوامل اختيار العاصمة؟)",m:3,kp:[["الحماية والدفاع: البعد عن الحدود يعطي الدولة عمقاً جغرافياً ويوفر لها الحماية (مثل اختيار أنقرة بدلاً من إستانبول)",2],["عوامل أخرى: العامل التاريخي (القاهرة، روما)، سهولة الوصول (مدريد، الخرطوم على النيل، نواكشوط على الساحل)، السيادة القومية (موسكو في منطقة الغالبية السلافية)",2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 الدرس 2 المقومات الطبيعية",q:"ما العلاقة بين مساحة الدولة وقوتها؟ (آثار المساحة الكبيرة والصغيرة)",m:2,kp:[["المساحة الكبيرة: تنوع التركيب الجيولوجي والموارد المعدنية (روسيا والصين)، نظرية الدفاع بالعمق، استيعاب عدد كبير من السكان، إبعاد المصانع والسكان عن مناطق العدوان وقت الحرب، لكنها تحتاج جهوداً كبيرة للتطوير والحماية والسيطرة",2],["المساحة الصغيرة: سهولة الضبط والإدارة وتنمية جميع الأجزاء وحصر الموارد، لكنها أكثر عرضة للاحتلال (ألمانيا على هولندا وبلجيكا) وتأثراً بالكوارث الطبيعية",2],["أهمية المساحة لا تقاس بالكيلومترات فقط بل بعدد السكان وتوزيعهم والنظم الاقتصادية وقدرة السكان العلمية وسهولة الاتصال",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 الدرس 2",q:"اذكر مميزات الدولة ذات الشكل المندمج (المنتظم).",m:2,kp:[["قدرة الحكومة على تحقيق أفضل اتصال وسيطرة لأن الأطراف على أبعاد متساوية تقريباً من المركز",1.5],["حسن الإدارة الداخلية",1],["يقلل فرص الاحتكاك والنزاع على الحدود لأن طول الحدود قصير بالنسبة للمساحة. أمثلة: مصر وبلجيكا وفرنسا",1.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 الدرس 4 النظام السياسي",q:"قارن بين النظام الرئاسي والنظام البرلماني.",m:4,kp:[["الرئاسي: استقلال كامل للسلطات الثلاث وكل سلطة في اختصاصها، والنموذج الأشهر النظام الأمريكي",2],["البرلماني: برلمان منتخب مصدر السلطة والتشريع، رئيس أو ملك يسود ولا يحكم، ورئيس الوزراء يتولى مسئولية الحكم، ونموذجه المملكة المتحدة",2],["شبه الرئاسي: وسط بينهما، رئيس منتخب مباشرة على رأس السلطة التنفيذية وبرلمان منتخب يشكل الحكومة (فرنسا)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 الدرس 1 الحدود السياسية",q:"دلل جغرافياً على صحة العبارة: تتعدد وظائف الحدود السياسية في العالم.",m:3,kp:[["الفصل بين الدول: اتفاقيات موثقة وخرائط، وحواجز ونقاط تفتيش ومراكز حراسة ومناطق جمركية وعلامات حدود",1.5],["الحماية والأمن: الوظيفة الأكثر أهمية قديماً (دفاعات عسكرية ومراقبة جوية وأقمار صناعية)، وأثرت التطورات الحديثة في الأسلحة (المدى والسرعة وتخطي العقبات) فسقطت نظرية الحد الآمن",1.5],["الحماية الاقتصادية: تحدد نصيب كل دولة من الموارد وتراقب تدفق السلع وتمنع التهريب وتفرض الرسوم الجمركية وتفحص جودة المستورد، وتعين الحدود بدقة وتعقد اتفاقيات لاقتسام الثروات على جانبي الحد (البترول والغاز بين دول الخليج، وبين ليبيا وتونس)",2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 الدرس 2 أنواع الحدود",q:"اذكر مميزات وعيوب الحدود النهرية.",m:2,kp:[["مميزات: واضحة في الطبيعة، وتمثل خطاً دفاعياً ومانعاً مائياً",1.5],["عيوب: الأنهار تغير مجاريها (الفيضان والنحت والإرساب) فتتغير الضفاف، مثل نهر ريو غراندي بين الولايات المتحدة والمكسيك الذي تحولت مناطق بتغير مجراه، ووجود جزر في المجرى قد يعوق تحديد الحد",2.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 الدرس 2",q:"اذكر أهمية الحدود البحرية للدولة.",m:2,kp:[["حماية الحدود من السفن المشبوهة (الحماية والأمن)",1],["حماية الاقتصاد بمنع التهريب، وحقوق اقتصادية (ثروات ومصايد) وعسكرية",1],["الوقاية من الأوبئة بالتفتيش الصحي للسفن عند دخول المياه الإقليمية",1],["النزاع على الحد البحري مع كل دول العالم فيجب تحديده بدقة، وزادت أهمية الرصيف القاري بعد اكتشافات البترول والغاز",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 الدرس 2",q:"ما الحدود الهندسية؟ وأين تشيع؟ مع التمثيل بمصر.",m:2,kp:[["حدود فلكية تتفق مع خطوط الطول ودوائر العرض، أو خطوط مستقيمة بين نقطتين، أو على أبعاد متساوية من ساحل أو سلسلة جبلية",1.5],["تشيع في إفريقيا وأمريكا الشمالية، وتمتد في مناطق قليلة السكان أو خالية من الموارد",1.5],["أمثلة: الحد بين مصر والسودان على دائرة عرض 22 شمالاً، وبين مصر وليبيا على خط طول 25 شرقاً (باستثناء الجزء الشمالي)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 الدرس 3 تطور الخريطة",q:"ما النتائج المترتبة على تأثير الحربين العالميتين الأولى والثانية على خريطة العالم السياسية؟",m:2,kp:[["تغيرات سريعة: اختفت دول وظهرت دول وعُدلت حدود دول واختفت إمبراطوريات وحل محلها قوى عظمى جديدة",2],["انقسام ألمانيا إلى شرقية وغربية",1],["بداية الخمسينيات: الاستقطاب العالمي بين الكتلة الشيوعية (الاتحاد السوفيتي) والرأسمالية (الولايات المتحدة) ودول عدم الانحياز",2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 الدرس 3",q:"اذكر تغيرات خريطة العالم السياسية في أواخر القرن العشرين.",m:2,kp:[["انهيار الكتلة الشيوعية وتفكك الاتحاد السوفيتي ويوغوسلافيا وانفراط حلف وارسو",1.5],["اتحاد ألمانيا الشرقية والغربية",1],["انتصار الرأسمالية بزعامة الولايات المتحدة وانفرادها بالزعامة",1],["السمة الأساسية للخريطة التغير المستمر (بطيء وسريع)",.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],geology:[{l:"الباب 1 علم الجيولوجيا ومادة الأرض",q:"ماذا يقصد بعملية الطي وما أهميتها وما الأنواع الناتجة عنها؟",m:2,kp:[["الطية: انثناء أو جعد يحدث لصخور القشرة الأرضية، وتنشأ غالباً نتيجة قوى الضغط، وتظهر بوضوح في الصخور الرسوبية الطباقية",1.5],["الأنواع الأكثر شيوعاً: الطية المحدبة (طبقاتها منحنية لأعلى وأقدم طبقاتها في المركز) والمقعرة (منحنية لأسفل وأحدث طبقاتها في المركز)",1.5],["الأهمية: تشكل مصايد البترول والمياه الجوفية وترسب الخامات، وتحدد العلاقة الزمنية بين الصخور، ويستدل منها على أحداث جيولوجية",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب 1",q:"ما خصائص الفالق العادي والفالق المعكوس؟ واذكر أهمية الفوالق.",m:2,kp:[["الفالق: كسر في الكتل الصخرية يصاحبه حركة نسبية لجانبي مستوى الكسر (عناصره: مستوى الفالق، الحائط العلوي، الحائط السفلي)",1],["العادي: ينتج عن الشد وتتحرك فيه صخور الحائط العلوي لأسفل بالنسبة للسفلي",1.5],["المعكوس: ينشأ من الضغط وتتحرك صخور الحائط العلوي لأعلى بالنسبة للسفلي",1.5],["الأهمية: مصايد للبترول والغاز والمياه، ينابيع ساخنة (حلوان، العين السخنة)، ترسيب خامات (كالسيت ومنجنيز ونحاس وقصدير)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب 1",q:"علل: يسمى الفالق الدسر بالفالق الزحفى.",m:4,kp:[["الفالق الدسر نوع من الفوالق المعكوسة مستواه أفقي تقريباً (قليل الميل)",1],["فصخوره المهشمة تزحف أفقياً تقريباً مسافة على مستوى الفالق",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب 1",q:"قل ما تعرفه عن السواتر (الفوالق البارزة) والفوالق الخسفية والفالق ذو الحركة الأفقية.",m:3,kp:[["الفالق البارز (الساتر): يحدث عندما تتأثر الصخور بفالقين عاديين يتحدان معاً في صخور الحائط السفلي",1.5],["الفالق الخندقي (الخسفي): فالقان عاديان يتحدان في صخور الحائط العلوي",1.5],["الفالق ذو الحركة الأفقية: تتحرك صخوره المهشمة أفقياً في نفس المستوى دون إزاحة رأسية",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب 1",q:"اذكر الشواهد الدالة على وجود الفوالق.",m:2,kp:[["انصقال جوانب الفالق مع وجود خطوط موازية لحركة الصخور",1.5],["وجود بريشيا الفوالق: فتات من الصخور المهشمة ذات حواف حادة",1.5],["تصاعد نافورات المياه وترسيب المعادن على طول مستوى الفالق",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب 3 الصخور",q:"اذكر أنواع الصخور الموجودة في الطبيعة موضحاً الفرق بينها.",m:2,kp:[["النارية: نتجت من تبريد وتبلور المادة المنصهرة (أم الصخور)، كتلية الشكل متبلرة غير مسامية لا تحتوي أحافير (الجرانيت، البازلت، الأنديزيت)",1.5],["الرسوبية: من تفتيت صخور قديمة ونقل الفتات وترسيبه وتماسكه، طباقية نادرة التبلر غالباً مسامية وتحتوي أحافير (الحجر الرملي، الطيني، الجيري)",1.5],["المتحولة: نارية أو رسوبية تأثرت بحرارة أو ضغط أو بهما فتحولت إلى صخور بصفات جديدة، ورقية أو كتلية متبلرة غير مسامية (الرخام، الشيست)",1.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب 3",q:"ما مراحل دورة الصخور؟ اشرح كل مرحلة، وما العلاقة بين الأنواع الثلاثة؟",m:2,kp:[["اكتشفها هاتون (1788 تقريباً): العمليات التي تحول نوعاً من الصخور إلى آخر في دورة واحدة",.5],["التجوية: تفتيت وتحلل الصخور بعوامل الجو (ميكانيكية وكيميائية)",1],["النقل: إلى أحواض الترسيب بالأنهار والثلاجات والرياح والماء",1],["الترسيب: تراكم الفتات في المناطق المنخفضة في طبقات أفقية",1],["التحجر (التصخر): ضغط وتلاصق الحبيبات وترسيب مادة لاحمة فتتحول الرواسب إلى صخور رسوبية صلبة",1],["العلاقة: النارية أصل الصخور؛ منها تنتج الرسوبية بالتجوية والنقل والترسيب، والمتحولة بالحرارة والضغط من أي نوع، وكلها قد تنصهر وتتبلر مرة أخرى فتنتج نارية",1.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الباب 1",q:"عرّف: الحفرية المرشدة، الجيولوجيا، الفاصل.",m:2,kp:[["الجيولوجيا: علم الأرض ويتناول مكوناتها وحركاتها وتاريخها وظواهرها وثرواتها",1],["الفاصل: كسر في الصخور (نارية ورسوبية ومتحولة) بدون أي إزاحة، والمسافة بين الفواصل من سنتيمترات إلى عشرات الأمتار",1],["الحفرية المرشدة: حفرية ذات انتشار جغرافي واسع ومدى زمني محدود تستخدم لتحديد عمر الطبقات",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],history:[{l:"الفصل 1 الحملة الفرنسية",q:"اذكر أسباب قدوم الحملة الفرنسية على مصر عام 1798.",m:2,kp:[["التنافس الاستعماري بين إنجلترا وفرنسا بعد الثورة الفرنسية 1789، ورغبة فرنسا في توجيه ضربة لإنجلترا بعد تعذر غزوها مباشرة بسبب تفوق الأسطول الإنجليزي",1],["تسهيل مرور التجارة الفرنسية إلى الشرق بدلاً من طريق رأس الرجاء الصالح الذي يسيطر عليه الأسطول الإنجليزي",1],["تقويض الإمبراطورية البريطانية في الشرق",1],["رغبة فرنسا في إنشاء مستعمرة فرنسية في الشرق (فكرة قديمة من عهد لويس الرابع عشر)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 1",q:"وضّح أحوال المجتمع المصري قبيل الحملة الفرنسية (اقتصادياً واجتماعياً وسياسياً).",m:3,kp:[["اقتصادياً: الأرض ملك الدولة ويجمع الضرائب الملتزمون ويظلمون الفلاحين، الصناعة يدوية في طوائف، تدهور التجارة بعد تحول الطريق إلى رأس الرجاء الصالح وسيطرة التجار الأجانب بالامتيازات",1.5],["اجتماعياً: فئتان: الحكام (الأتراك والمماليك) في عزلة، والمحكومون (علماء وتجار وفلاحون وحرفيون) وانتشر الجهل والخرافات ولم يبق من العلم إلا الأزهر",1],["سياسياً: ثلاث قوى تتراقب: الوالي (نائب السلطان) والديوان (يراقب الوالي) والبكوات المماليك (إدارة الأقاليم)",1.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 1",q:"تحدث عن مقاومة المصريين للحملة الفرنسية.",m:3,kp:[["أهالي الإسكندرية بزعامة السيد محمد كريم (أُعدم)",1],["المماليك في شبراخيت وإمبابة (هُزموا وفرّ مراد بك للصعيد ودخل نابليون القاهرة يوليو 1798)",1],["ثورة القاهرة الأولى (أكتوبر 1798) بقيادة الأزهر، وقُمعت ودخل الفرنسيون الأزهر بخيولهم",1],["مقاومة الصعيد نحو عشرة أشهر بحرب المناوشات وطول الوادي",1],["ثورة القاهرة الثانية، ثم قتل سليمان الحلبي كليبر (يونية 1800)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 1",q:"قارن بين ثورتي القاهرة الأولى والثانية.",m:4,kp:[["الأولى: أكتوبر 1798، قادها الأزهر وعلماؤه ضد سياسة الحاكم الفرنسي وضرائبه، قُمعت بعنف مع دخول الأزهر",1.5],["الثانية: 1800 بعد معاهدة العريش ورفض إنجلترا لها واستغلال المصريين لمتاعب الفرنسيين، أخمدها كليبر في الوجه البحري واتفق مع مراد بك على الصعيد",1.5],["نتيجة مشتركة: فشلت عسكرياً لكنها أبرزت الزعامة الشعبية وروح المقاومة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 1",q:"ما الآثار السياسية والفكرية للحملة الفرنسية على مصر؟",m:2,kp:[["سياسياً: إنشاء دواوين القاهرة والأقاليم والديوان العام لتدريب الأعيان على الشورى، لكن سلطتها مقيدة بالمصالح الفرنسية وفي ظل نقل شكلي للسلطة للطبقة الوسطى",1.5],["فكرياً: علماء وفنانون صحبوا الحملة، وإنشاء المجمع العلمي المصري على غرار المجمع الفرنسي لربط السياسة بالعلم",1.5],["اقتصادياً: تجارب زراعية (البن وقصب السكر)، مصانع، الحجر الصحي، تنظيم القضاء",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 2 بناء الدولة الحديثة",q:"كيف وصل محمد علي إلى حكم مصر؟",m:3,kp:[["بعد خروج الفرنسيين تنازع الحكم ثلاث قوى: العثمانيون والمماليك والإنجليز، ثم برزت قوة الشعب المصري (الزعامة الشعبية)",1.5],["محمد علي قائد الأرناؤود ناور بين القوى؛ وتخلص خورشيد باشا منه بالسعي لنقله وإرسال الدلاة، فاشتد غضب الناس",1],["في مايو 1805 اجتمع العلماء ونقباء الطوائف وعزلوا خورشيد وولّوا محمد علي بعهد أن يسير بالعدل ولا يبرم أمراً إلا بمشورتهم، وأقرّ السلطان ذلك",1.5],["أهمية الحدث: أول مرة يعزل فيها الوالي ويعين بإرادة الشعب (صك اجتماعي أول)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 2",q:"اذكر الإجراءات التي اتخذها محمد علي لتوطيد سلطته.",m:2,kp:[["مواجهة الخطر المملوكي الإنجليزي: صد هجمات المماليك، وإفشال حملة فريزر 1807 (بمقاومة المصريين في رشيد والحماد ثم حصار الإسكندرية)",1.5],["القضاء على الزعامة الشعبية: استغل الأزمة وانقسام الزعماء ونفى عمر مكرم إلى دمياط وولّى السادات",1.5],["مذبحة القلعة (مارس 1811) للقضاء على المماليك ثم مطاردة بقاياهم",1],["الانفراد بالحكم دون وصاية شعبية",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 3 من الثورة العرابية",q:"اذكر أسباب الثورة العرابية (الضباط المصريون).",m:2,kp:[["الأزمة المالية والتدخل الأوروبي منذ عهد إسماعيل وعزله، والرقابة الثنائية، وتدهور الأوضاع",1],["تذمر ضباط الجيش المصري: تفضيل الضباط الأتراك والشراكسة، قصر الترقية على خريجي المدارس الحربية، إحالة كثير من الضباط للمعاش، وسوء معاملة وزير الحربية عثمان رفقي",2],["طابع الثورة المدني رغم قيادة العسكريين (مناخ عام منذر بالثورة)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 3",q:"قارن بين مظاهرة عابدين الأولى (1881 فبراير) ومظاهرة عابدين الثانية (9 سبتمبر 1881) من حيث الأسباب والنتائج.",m:4,kp:[["الأولى (حادثة قصر النيل): الضباط عرابي وعلي فهمي وعبد العال حلمي يخرجون بفرقهم لمنع محاكمتهم ويطلبون عزل عثمان رفقي؛ النتيجة عزله وتعيين محمود سامي البارودي وزيراً للحربية واستجابة لمعظم المطالب الفئوية",2],["الثانية: بعد تضييق الخديو ونقل الضباط ومحاولات تفريقهم؛ رفع عرابي مطالب الجيش والأمة: عزل رياض باشا وتشكيل مجلس النواب وزيادة الجيش إلى 18 ألف",1.5],["نتيجة الثانية: عزل رياض وتكليف شريف بتشكيل الوزارة والبارودي وزيراً للحربية، ثم نقل الضباط، وتأكد الطابع السياسي للحركة",1.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 5 التوسع الاستعماري",q:"وضّح أسباب التوسع الفرنسي في شمال إفريقيا وأساليب الاستعمار الأوروبي.",m:3,kp:[["التنافس الاستعماري على الأسواق ومصادر المواد الخام بعد الثورة الصناعية، وسقوط معظم البلاد العربية تحت قبضة الاستعمار قبل 1914",1.5],["أساليب الاستعمار السياسي: تقسيم الوطن العربي وإثارة النعرات المحلية والاتفاقيات الدولية",1.5],["مواجهة المقاومة المحلية والدور الريادي لمصر في دعم استقلال شعوب شمال إفريقيا (وفق أهداف الفصل)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 6",q:"وضّح أسباب دخول العرب الحرب العالمية الأولى ضد الدولة العثمانية، وقيّم اتفاقية سايكس بيكو.",m:3,kp:[["سياسة التتريك والاستبداد العثماني، وسعي الشريف حسين للاستقلال ووعود بريطانيا (مراسلات حسين مكماهون)",1.5],["سايكس بيكو (1916): اتفاق إنجلترا وفرنسا على تقسيم البلاد العربية إلى مناطق نفوذ سراً",1.5],["تقييمها: تناقضت مع الوعود للعرب ومثلت طمعاً استعمارياً وقوّضت الوحدة العربية",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 7 مصر وقضايا العالم العربي",q:"قارن بين حرب يونيو 1967 وحرب أكتوبر 1973 من حيث الأسباب والنتائج.",m:4,kp:[["يونيو 1967: هزيمة عسكرية واحتلال سيناء والضفة والجولان وغزة",1.5],["أكتوبر 1973: عبور القناة وتحطيم خط بارليف واسترداد الكرامة وفتح باب التفاوض",1.5],["الدروس المستفادة: أهمية الوحدة العربية والإعداد الجيد والتخطيط والسرية",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الفصل 8 ثورتا 25 يناير و30 يونيو",q:"اذكر أسباب ثورة 25 يناير 2011.",m:2,kp:[["تزوير انتخابات مجلس الشعب (نوفمبر 2010) بالكامل لصالح الحزب الوطني",1],["سوء الأوضاع الاقتصادية",1],["استمرار العمل بقانون الطوارئ",1],["مطالب الثوار: الحرية والكرامة والعدالة الاجتماعية، وتصاعد المطالب بإسقاط النظام",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],ict:[{l:"النظم العددية - مقدمة",q:"فرّق بين الرقم (Digit) والعدد (Number) مع مثال.",m:3,kp:[["الرقم: قيمة رمز واحد من الرموز الأساسية يحتل خانة واحدة (0، 1، 6، 8)",1],["العدد: المقدار العددي المكون من رقم واحد أو أكثر (26 من رقمين، 264 من ثلاثة، 1679 من أربعة)",1],["الرقم الواحد يمكن أن يكون عدداً إذا كانت سلسلته رقماً واحداً",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"النظم العددية",q:"قارن بين النظام العشري والثنائي والسداسي عشر من حيث الأساس والرموز.",m:4,kp:[["العشري: أساسه 10، رموزه 0-9 (الأقدم والأكثر استخداماً)",1],["الثنائي: أساسه 2، رموزه 0 و1 (لغة الكمبيوتر)",1],["السداسي عشر: أساسه 16، رموزه 0-9 و A-F حيث A=10، B=11، C=12، D=13، E=14، F=15",1],["في كل نظام لكل رقم رتبة (وزن) هي قوة الأساس حسب موضعه",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"التحويل: العشري إلى الثنائي",q:"حوّل العدد (25) من النظام العشري إلى الثنائي موضحاً الخطوات.",m:3,kp:[["القسمة المتكررة على 2 مع تسجيل الباقي حتى يصير الناتج صفراً: 25÷2=12 باقي 1، 12÷2=6 باقي 0، 6÷2=3 باقي 0، 3÷2=1 باقي 1، 1÷2=0 باقي 1",1.5],["قراءة البواقي من آخر باقٍ إلى أول باقٍ",.5],["الناتج: (25)₁₀ = (11001)₂",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"التحويل: الثنائي إلى العشري",q:"حوّل العدد الثنائي (1101) إلى النظام العشري.",m:3,kp:[["اضرب كل رقم في 2 مرفوعة لرتبته من اليمين (من 0): 1×2³ + 1×2² + 0×2¹ + 1×2⁰",1.5],["= 8 + 4 + 0 + 1",.5],["الناتج: (1101)₂ = (13)₁₀",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"التحويل: السداسي عشر إلى العشري",q:"حوّل العدد (2F) من النظام السداسي عشر إلى العشري.",m:3,kp:[["2F: الرقم 2 رتبة 16¹ و F=15 رتبة 16⁰: 2×16 + 15×1",1.5],["= 32 + 15",.5],["الناتج: (2F)₁₆ = (47)₁₀",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"التحويل: العشري إلى السداسي عشر",q:"حوّل العدد (255) من العشري إلى السداسي عشر.",m:3,kp:[["القسمة على 16 مع تسجيل الباقي: 255÷16=15 باقي 15 (F)، 15÷16=0 باقي 15 (F)",1.5],["قراءة البواقي من الأخير للأول",.5],["الناتج: (255)₁₀ = (FF)₁₆",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"التحويل: السداسي عشر والثنائي",q:"حوّل العدد (A7) من السداسي عشر إلى الثنائي، ثم الثنائي (10110110) إلى السداسي عشر.",m:3,kp:[["كل رقم سداسي عشر يكافئ 4 خانات ثنائية: A=1010، 7=0111",1],["(A7)₁₆ = (10100111)₂",1],["العكس: قسّم الثنائي من اليمين لمجموعات من 4: 1011 و0110 = B و6",.5],["(10110110)₂ = (B6)₁₆",.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"مشروع التحويل بلغة VB.NET / PHP",q:"اذكر المهارات والخطوات الأساسية لتنفيذ مشروع برمجي لتحويل عدد بين النظم العددية.",m:"3",kp:[["تحديد المدخلات (العدد والنظام المدخل) والمخرجات (العدد المحول)",1],["تصميم واجهة المشروع (مربعات نص وأزرار وقائمة اختيار) بـ VB.NET أو صفحة HTML مع PHP",1],["كتابة الشفرة التي تنفذ خوارزمية التحويل (القسمة المتكررة والبواقي) وتجربة المشروع بأمثلة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],physics:[{l:"الفيزياء الحديثة - الأشعة السينية",q:"إذا كان فرق الجهد بين المهبط والمصعد في أنبوبة كوليدج V = 50 kV، احسب أقصر طول موجي للأشعة السينية الناتجة، ثم وضح كيف يمكن تقليل الطول الموجي عملياً وتأثير ذلك على قدرة الأشعة على الاختراق.",m:2,kp:[["أقصر طول موجي يحدث عندما تتحول كل طاقة الإلكترون eV إلى فوتون واحد: eV = hc/λmin",.5],["λmin = hc/(eV) = (6.625×10^-34 × 3×10^8)/(1.6×10^-19 × 50×10^3) ≈ 2.48×10^-11 m (≈0.248 Å)",.75],["لتقليل الطول الموجي: زيادة فرق الجهد بين المهبط والمصعد",.35],["بنقص الطول الموجي تزداد طاقة الفوتون فتزداد قدرة الاختراق (أشعة صلبة)",.4]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"الفيزياء الحديثة - الطبيعة الجسيمية للضوء",q:"فوتون (X) طوله الموجي 320 nm وفوتون (Y) طوله الموجي λ، وكمية تحرك الفوتون (X) ثلاثة أمثال كمية تحرك (Y). احسب λ للفوتون Y وحدد المنطقة التي ينتمي إليها.",m:2,kp:[["كمية تحرك الفوتون p = h/λ أي أن λ تتناسب عكسياً مع p",.5],["pX = 3pY ⟹ λY = 3λX",.5],["λY = 3 × 320 = 960 nm",.5],["960 nm أكبر من 700 nm فهو في منطقة الأشعة تحت الحمراء (كما ذكر السؤال)",.5]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"الفيزياء الحديثة - طيف ذرة الهيدروجين",q:"أربعة انتقالات لذرة الهيدروجين: 2→5، 3→6، 7→4، 4→1. عيّن أقصى طاقة بالجول تمتصها الذرة.",m:2,kp:[["الامتصاص يحدث عند الانتقال لمستوى أعلى (2→5 و3→6 فقط)، أما 7→4 و4→1 فانبعاث",.5],["E = 13.6 (1/n1² − 1/n2²) eV",.3],["2→5: 13.6(1/4 − 1/25) = 2.856 eV ؛ 3→6: 13.6(1/9 − 1/36) = 1.133 eV",.6],["الأقصى 2→5: 2.856 × 1.6×10^-19 ≈ 4.57×10^-19 J",.6]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"أجهزة القياس الكهربي - الأوميتر",q:"أوميتر مقاومته R ينحرف مؤشره إلى صفر التدريج عند تيار 400 μA. وصلت مقاومة Rx فانحرف المؤشر إلى ثُمن تدريج التيار. احسب النسبة R : Rx.",m:2,kp:[["عند توصيل الطرفين معاً: Ig = V/R",.5],["بعد توصيل Rx: I = Ig/8 = V/(R+Rx)",.5],["R + Rx = 8R ⟹ Rx = 7R",.6],["R/Rx = 1/7",.4]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"الحث المتبادل - المحولات",q:"محول خافض كفاءته 80%: جهد الابتدائي 250 V وتياره 0.5 A، جهد الثانوي 10 V وعدد لفاته 200. احسب (1) عدد لفات الابتدائي (2) المقاومة R المتصلة بالثانوي.",m:2,kp:[["Np/Ns = Vp/Vs ⟹ Np = 200 × 250/10 = 5000 لفة",.8],["η = (Vs Is)/(Vp Ip) ⟹ 0.8 = (10 × Is)/(250 × 0.5)",.5],["Is = 10 A",.3],["R = Vs/Is = 10/10 = 1 Ω",.4]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"التأثير المغناطيسي للتيار - الملف اللولبي",q:"ملف لولبي عدد لفاته N متصل ببطارية VB مهملة المقاومة الداخلية، يمر به تيار I وكثافة الفيض عند نقطة على محوره B. احسب كثافة الفيض بدلالة B عند إضافة ثلث عدد اللفات وتوصيله بنفس البطارية.",m:2,kp:[["B = μ N I / L (طول الملف L ثابت)",.4],["العدد الجديد N' = 4N/3 فيزداد طول السلك والمقاومة إلى 4R/3 (نفس نوع السلك ونفس مساحته)",.6],["I' = VB/R' = 3I/4",.4],["B' = μ (4N/3)(3I/4)/L = B أي لا تتغير",.6]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"الحث الكهرومغناطيسي - المولد",q:"سلك طوله L لُف على شكل ملف مربع من لفة واحدة يدور بسرعة زاوية ω بين قطبي مغناطيس كثافة فيضه B فكانت emf العظمى V. احسب emf العظمى بدلالة V إذا لُف سلك طوله 2L كملف مربع يدور بنفس السرعة.",m:2,kp:[["emf max = B A ω (لفة واحدة)",.4],["ضلع المربع = L/4 فالمساحة L²/16 ؛ للسلك 2L: الضلع L/2 والمساحة L²/4",.7],["المساحة تصبح 4 أمثال",.4],["emf' = 4V",.5]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"الفيزياء الحديثة - الطبيعة الجسيمية للضوء",q:"الشكل البياني يوضح العلاقة بين القوة F التي يؤثر بها شعاع فوتونات على سطح عاكس تماماً والمعدل الزمني لسقوط الفوتونات (dN/dt). احسب الكتلة المكافئة لأحد الفوتونات.",m:2,kp:[["لسطح عاكس تماماً: F = 2 (dN/dt) p لأن التغير في كمية التحرك للفوتون = 2p",.6],["ميل الخط = F/(dN/dt) = 2p ⟹ p = الميل/2",.5],["p = m c ⟹ الكتلة المكافئة m = الميل/(2c)",.7],["عوّض بقيمة الميل المقروءة من الرسم",.2]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"التيار الكهربي وقانون أوم",q:"تيار شدته 3.2 mA يمر في سلك. احسب معدل مرور الإلكترونات عبر مقطع من السلك.",m:1,kp:[["معدل مرور الإلكترونات = I/e",.4],["I = 3.2×10^-3 A ، e = 1.6×10^-19 C",.3],["= 2×10^16 إلكترون/ثانية",.3]],lab:"الإجابة المنشورة بالمصدر (غير رسمية) + مراجعة المنصة"},{l:"التيار الكهربي وقانون أوم",q:"كيف يمكنك زيادة المقاومة الكهربية لسلك نحاس عند درجة حرارة ثابتة؟",m:1,kp:[["R = ρ L/A",.3],["بزيادة الطول أو بإنقاص مساحة المقطع",.4],["لأن R تتناسب طردياً مع L وعكسياً مع A",.3]],lab:"الإجابة المنشورة بالمصدر (غير رسمية) + مراجعة المنصة"},{l:"التيار الكهربي وقانون أوم",q:"وضح السبب العلمي: المقاومة النوعية لمادة موصل خاصية فيزيائية مميزة لها عند ثبوت درجة الحرارة.",m:1,kp:[["لأنها تتوقف على نوع المادة ودرجة الحرارة فقط",.6],["ولا تتغير بتغير الطول أو مساحة المقطع",.4]],lab:"الإجابة المنشورة بالمصدر (غير رسمية) + مراجعة المنصة"},{l:"أجهزة القياس الكهربي",q:"لماذا تكون قراءة الجلفانومتر لشدة التيار في دائرة أقل دائماً من شدة التيار بدونه؟",m:1,kp:[["لأن للجلفانومتر مقاومة تتصل على التوالي",.4],["تزيد المقاومة الكلية للدائرة",.3],["I = V/Rtotal فتقل شدة التيار",.3]],lab:"الإجابة المنشورة بالمصدر (غير رسمية) + مراجعة المنصة"},{l:"قانون أوم للدائرة المغلقة",q:"بطارية قوتها الدافعة 12 V ومقاومتها الداخلية 1 Ω توصل بمقاومة خارجية 5 Ω. احسب شدة التيار وفرق الجهد بين قطبي البطارية.",m:2,kp:[["emf = I(R + r)",.4],["I = 12/(5+1) = 2 A",.6],["VB = I R = 2×5 = 10 V (أو emf − I r = 12 − 2)",.6],["الوحدات",.4]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"توصيل المقاومات",q:"ثلاث مقاومات 6 Ω و3 Ω و2 Ω: احسب المقاومة المكافئة (1) على التوالي (2) على التوازي.",m:2,kp:[["توالي: R = 6+3+2 = 11 Ω",.8],["توازي: 1/R = 1/6+1/3+1/2 = 1",.8],["R = 1 Ω",.4]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"قانونا كيرشوف",q:"اذكر نص قانوني كيرشوف الأول والثاني ووضح على أي قانون يعتمد كل منهما.",m:2,kp:[["الأول: المجموع الجبري للتيارات عند نقطة تفرع = صفر (الداخل = الخارج)",.5],["يعتمد على بقاء الشحنة",.5],["الثاني: المجموع الجبري للقوى الدافعة = المجموع الجبري لفروق الجهد (IR) في مسار مغلق",.5],["يعتمد على بقاء الطاقة",.5]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"التأثير المغناطيسي للتيار (سلك)",q:"سلك مستقيم يمر به تيار 10 A. احسب كثافة الفيض عند نقطة تبعد 5 cm عنه (μ = 4π×10^-7 Wb/A.m).",m:2,kp:[["B = μ I /(2π d)",.6],["= 4π×10^-7 × 10/(2π × 0.05)",.6],["= 4×10^-5 T",.5],["الاتجاه بقاعدة اليد اليمنى",.3]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"القوى المغناطيسية وعزم الازدواج",q:"ملف مستطيل N لفة، مساحته A، يمر به تيار I في مجال B. اكتب العلاقة لعزم الازدواج واذكر متى يكون أكبر ما يمكن ومتى ينعدم.",m:2,kp:[["τ = N B I A sinθ (θ بين العمودي على الملف والمجال)",.8],["أكبر قيمة عندما θ = 90° (المستوى موازٍ للمجال)",.6],["ينعدم عندما θ = 0 (المستوى عمودي على المجال)",.6]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"},{l:"أجهزة القياس الكهربي",q:"وضح كيف يُحوَّل الجلفانومتر إلى أميتر ثم إلى فولتميتر مع كتابة العلاقة المستخدمة.",m:2,kp:[["أميتر: مجزئ تيار Rs على التوازي، Rs = Ig Rg/(I − Ig)",.7],["فولتميتر: مضاعف جهد Rm على التوالي، Rm = V/Ig − Rg",.7],["الأميتر مقاومته صغيرة والفولتميتر كبيرة",.4],["الأميتر يوصل توالي والفولتميتر توازي",.2]],lab:"من إعداد المنصة - ليست إجابة رسمية من الوزارة"}],psychology:[{l:"الوحدة 1 - الذكاء",q:"عرّف الذكاء من وجهة نظر جاردنر، ولماذا رفض فكرة أحادية الذكاء؟",m:2,kp:[["عرّف جاردنر (1983) الذكاء بأنه القدرة على حل المشكلات في سياقات مختلفة",1.5],["رفض فكرة الذكاء الواحد ونسبة الذكاء (IQ) التي تصنف الأفراد إلى أذكياء وغير أذكياء",1.5],["رأى أن للإنسان عدة كفاءات (ذكاءات متعددة) يملكها كل فرد بدرجات غير متساوية، وتتفاعل معاً لتنتج أداءً متميزاً، وهي قابلة للنمو",2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1",q:"عرّف الذكاء اللغوي كما حدده جاردنر، واذكر خصائص أصحابه وطرق تنميته.",m:2,kp:[["التعريف: قدرة الفرد على فهم واستخدام اللغة المنطوقة والمكتوبة بطلاقة ومرونة (القراءة والكتابة وتركيب الجمل وفهم المعاني والتواصل)",1.5],["الخصائص: طلاقة التحدث، دقة صياغة العبارات البلاغية، حب السجع والتلاعب بالألفاظ والألعاب الكلامية، دحض الحجة بالحجة، الخطابة (الشعراء والكتاب والمعلمون)",1.5],["التنمية: التدريب على كتابة التعبير، كتابة القصة والشعر والمقال والنشر في مجلة المدرسة، تسميع الكلمات والنصوص",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1",q:"عرّف الذكاء المنطقي الرياضي.",m:2,kp:[["القدرة على استخدام الأعداد والرموز المجردة بفاعلية وتنظيم العلاقات واستخدام لغة الأرقام في الوصف والتحليل والتصنيف",1.5],["والتفكير العقلاني والاستنتاج وحل المشكلات بطريقة علمية",1],["خصائصه: استنتاج العلاقات الرياضية، حب التعامل مع الأرقام، التفكير المنظم وإجراء التجارب",.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - التعلم الشرطي الكلاسيكي",q:"في ضوء نظرية الاشتراط الكلاسيكي لبافلوف عرّف: المثير الطبيعي، الاستجابة الطبيعية، المثير المحايد، المثير الشرطي، الاستجابة الشرطية.",m:3,kp:[["المثير الطبيعي: ما تنشأ عنه الاستجابة الطبيعية عند تقديمه في البداية (الطعام)",1],["الاستجابة الطبيعية: سيلان اللعاب نتيجة الطعام",.5],["المثير المحايد: لا تنشأ عنه استجابة سيلان اللعاب قبل اقترانه بالطبيعي (صوت الجرس)",1],["المثير الشرطي: المثير المحايد الذي أصبح بعد اقترانه عدة مرات بالطبيعي قادراً بمفرده على انتزاع الاستجابة",1.5],["الاستجابة الشرطية: سيلان اللعاب الناتج عن المثير الشرطي وحده",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1",q:"بيّن كيف يحدث كل من: الانطفاء، التدعيم، الاسترجاع التلقائي (مع مثال تربوي).",m:3,kp:[["التدعيم: تتوقف قوة المثير الشرطي على عدد مرات اقترانه بالمثير الطبيعي والفاصل الزمني بينهما؛ مثال: تشجيع المعلم للإجابة الصحيحة فوراً",1.5],["الانطفاء: تكرار المثير الشرطي دون أن يعقبه المثير الطبيعي فتتضاءل الاستجابة تدريجياً؛ مثال: عدم السماح للطالب بالإجابة إذا قال (أنا.. أنا) فتقل الفوضى",1.5],["الاسترجاع التلقائي: ظهور الاستجابة الشرطية مؤقتاً (بأقل قوة) عند تقديم المثير الشرطي بعد فترة من الانطفاء",2]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1",q:"اذكر التطبيقات التربوية لنظرية الاشتراط الكلاسيكي.",m:2,kp:[["تفسير تعلم الاستجابات الانفعالية (خوف، قلق) مثل خوف الطفل من طبيب الأسنان لارتباطه بخبرة الألم",1],["تعديل الاستجابات غير المرغوبة بالاشتراط المضاد (ربط الظلام بمثير مرغوب)",1],["تكوين اتجاهات موجبة نحو المدرسة (ربطها بأنشطة محببة)",1],["إحلال نماذج شرطية مرغوبة وإطفاء غير المرغوبة، وتعليم القراءة بربط الجملة بالصورة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - المحاولة والخطأ",q:"فسّر قانون الأثر وقانون الاستعداد عند ثورندايك مع مثال.",m:3,kp:[["قانون الأثر: قوة الارتباط بين المثير والاستجابة لا تنشأ من التكرار فقط بل من الأثر الطيب للتعزيز؛ يقوى الارتباط إذا حققت الاستجابة الإشباع والارتياح، ويضعف إذا لم تحققه",2],["مثال: الإجابة الصحيحة تشعرك بالارتياح فتتذكرها بسرعة وتقوى الرابطة",.5],["قانون الاستعداد: يفسر الأساس الفسيولوجي للارتياح وعدم الارتياح: يرتاح الفرد إذا كان مهيئاً للاستجابة وأُتيحت له، ويضيق إذا كان مهيئاً ولم تتح له الفرصة (والعكس إذا أُجبر دون استعداد)",1.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - الفصل 3",q:"اذكر مبادئ التعلم الجيد.",m:2,kp:[["الدافعية والتعلم: لا تعلم بدون دافع، ودوافع الإنسان تشمل الاجتماعية المكتسبة كتقدير الذات والإنجاز",1],["التعزيز والتعلم: الموجب (الجوائز والدرجات) والسلبي مع التغذية الراجعة",1],["الممارسة والتعلم: الموزعة أفضل من المركزة",1],["الدور الإيجابي للمتعلم (إعداد الدرس والتلخيص والمشاركة)",1],["قابلية التعلم للانتقال (العناصر المشتركة والفهم)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - الفصل 3",q:"حدّد أسس الاستذكار الفعال.",m:3,kp:[["الانتباه: وقت ومكان ثابتان بعيداً عن السرير، والتدرب في ظروف متغيرة، والتخلص من المشكلات النفسية أو اللجوء للأخصائي",1.5],["زيادة الرغبة: التفكير في الأهداف، التنافس مع الذات، وتحديد وقت لإنهاء المادة",1],["المشاركة النشطة: المراجعة وتدوين الملخصات والأسئلة والملاحظات",1],["استخدام طرق القراءة الجيدة: استعراض المادة أولاً، الربط بالمعلومات السابقة، البحث عن المبادئ العامة، عادات قراءة جيدة",1.5]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 - النمو الإنساني",q:"عرّف النمو، واذكر مراحل النمو من الميلاد حتى الطفولة المتأخرة.",m:2,kp:[["النمو سلسلة من الحلقات المتتابعة تبدأ بتلقيح البويضة وتنتهي بنهاية حياة الفرد",1],["مرحلة ما قبل الولادة ثم المهد (حتى نهاية الأسبوع الثاني) ثم الرضاعة (حتى نهاية السنتين)",1],["ثم الطفولة المبكرة (من الثانية إلى نهاية السادسة) ثم الطفولة المتأخرة (من السابعة حتى العاشرة للبنات والثانية عشرة للأولاد)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 - النمو الإنساني",q:"اذكر مراحل النمو من البلوغ حتى الشيخوخة.",m:2,kp:[["البلوغ (ما قبل المراهقة) ثم المراهقة المبكرة (من 13 أو 14 حتى 17) ثم المراهقة المتأخرة (من 17 حتى 21)",1],["الرشد المبكر (من 21 حتى 40) ثم وسط العمر (من 40 حتى 60)",1],["الشيخوخة من الستين حتى نهاية العمر",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 - العوامل المؤثرة في النمو",q:"عرّف الوراثة، وكيف تنتقل الصفات الوراثية؟",m:2,kp:[["الوراثة انتقال الصفات أو الخصائص الوراثية من الوالدين إلى الأبناء",1],["تنتقل عن طريق المورثات (الجينات) التي تحملها الكروموزومات",1],["توجد في البويضة المخصبة بالحيوان المنوي بعد التلقيح والإخصاب",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 - النمو المعرفي",q:"اشرح مرحلة العمليات العيانية (الحسية) عند بياجيه.",m:4,kp:[["هي إحدى مراحل النمو المعرفي التي حددها بياجيه ومرتبطة بمرحلة الطفولة المتأخرة",1],["يقصد بالعمليات العيانية القدرة على التفكير المنطقي في الأمور الحسية",1],["تسبقها مرحلة ما قبل العمليات التي يكون فيها التفكير حسياً متمركزاً حول الذات ولا يستطيع الطفل أن يركز على بعدين أو أكثر",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"علم الاجتماع - مؤسسات التنشئة",q:"عرّف المدرسة كمؤسسة اجتماعية، واذكر دورها.",m:2,kp:[["المدرسة منظمة رسمية كفلها المجتمع وأوكل إليها تربية النشء وتعليمهم بشكل ثقافي مقصود",1],["تنقل الثقافة وتكسب الأفراد أنماط السلوك والتفكير وتكوّن العادات والاتجاهات والقيم",1],["تعد حلقة وسطى بين الأسرة والحياة الاجتماعية الواسعة وتؤهل الطفل لمواجهة الحياة وممارسة دوره الاجتماعي والمهني",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"علم الاجتماع - مؤسسات التنشئة",q:"عرّف جماعة الرفاق، وما أهميتها؟",m:2,kp:[["جماعة تتكون من أفراد متقاربين في السن أو المستوى الدراسي أو السكن أو الميول والاتجاهات",1],["يربط بينهم روابط عاطفية واجتماعية، ولها نظام وتقاليد تمثل إطاراً مرجعياً للطفل والمراهق",1],["تظهر أهميتها في التوافق النفسي والاجتماعي في كل مراحل الحياة وخاصة الطفولة والمراهقة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],statistics:[{l:"الوحدة 1 - الدرس 1 الارتباط",q:"عرّف معامل الارتباط الخطي لبيرسون واذكر قانونه وتفسير قيمته.",m:3,kp:[["مقياس لدرجة واتجاه العلاقة الخطية بين متغيرين",1],["ر = (ن مج س ص − مج س × مج ص) ÷ √[(ن مج س² − (مج س)²)(ن مج ص² − (مج ص)²)]",1.5],["−1 ≤ ر ≤ 1: موجب طردي، سالب عكسي، قريب من الصفر ضعيف، ±1 تام، 0 لا علاقة خطية",1.5]],lab:"من إعداد المنصة (قوانين قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - الدرس 1",q:"اذكر قانون معامل ارتباط الرتب لسبيرمان ومتى يستخدم.",m:3,kp:[["ر = 1 − (6 مج ف²) ÷ [ن (ن² − 1)] حيث ف الفرق بين رتبتي كل زوج",2],["يستخدم للبيانات الوصفية أو الترتيبية أو عند عدم دقة القياسات",1]],lab:"من إعداد المنصة (قوانين قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - الدرس 2 الانحدار",q:"أوجد معادلة خط انحدار ص على س (الصيغة والقانون) واذكر فائدته.",m:3,kp:[["معادلة خط الانحدار: ص^ = أ + ب س",1],["ب = (ن مج س ص − مج س مج ص) ÷ (ن مج س² − (مج س)²)، و أ = متوسط ص − ب × متوسط س",1.5],["الفائدة: التنبؤ بقيمة ص عند قيمة معلومة لـ س (داخل مدى البيانات)",.5]],lab:"من إعداد المنصة (قوانين قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 - مقاييس متقدمة",q:"اذكر طريقة حساب الربيعات ونصف المدى الربيعي وفائدته.",m:3,kp:[["الربيع الأول ر1 (ترتيب 25%)، الأوسط ر2 = الوسيط، الثالث ر3 (ترتيب 75%)",1],["المدى الربيعي = ر3 − ر1، ونصف المدى الربيعي = (ر3 − ر1) ÷ 2",1],["مقياس تشتت لا يتأثر بالقيم الشاذة، ويمثل بيانياً بالصندوق ذي العارضتين",1]],lab:"من إعداد المنصة (قوانين قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 3 - الاحتمال",q:"عرّف الاحتمال الشرطي واذكر قانون الضرب والأحداث المستقلة.",m:3,kp:[["ل(أ | ب) = ل(أ ∩ ب) ÷ ل(ب)، ل(ب) ≠ 0",1.5],["ل(أ ∩ ب) = ل(ب) × ل(أ | ب)",1],["أ، ب مستقلان إذا كان ل(أ ∩ ب) = ل(أ) × ل(ب) (أي ل(أ | ب) = ل(أ))",1.5]],lab:"من إعداد المنصة (قوانين قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 4 - المتغيرات العشوائية",q:"اذكر قانونَي التوقع والتباين للمتغير العشوائي المتقطع.",m:3,kp:[["التوقع ت(س) = مج س × د(س) (المتوسط)",1.5],["التباين = ت(س²) − [ت(س)]² حيث ت(س²) = مج س² د(س)",1.5],["مجموع قيم دالة الاحتمال = 1 وكل قيمة بين 0 و1",1]],lab:"من إعداد المنصة (قوانين قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 4 - الدرس 3",q:"قارن بين التوزيع الهندسي وتوزيع ذي الحدين.",m:4,kp:[["ذو الحدين: ن تجربة مستقلة، نجاح أو فشل، احتمال النجاح ل ثابت؛ ل(س = ك) = ن_ك ل^ك (1−ل)^(ن−ك)؛ التوقع ن ل؛ التباين ن ل (1−ل)",2],["الهندسي: عدد المحاولات حتى أول نجاح؛ ل(س = ك) = (1−ل)^(ك−1) ل؛ التوقع 1 ÷ ل",2]],lab:"من إعداد المنصة (قوانين قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 5 - التوزيع الطبيعي",q:"اذكر خصائص منحنى التوزيع الطبيعي وكيف تحوّل إلى المعياري.",m:3,kp:[["المنحنى جرسي متماثل حول المتوسط μ، والوسط = الوسيط = المنوال، والمساحة الكلية = 1",1.5],["التحويل: ز = (س − μ) ÷ σ، فيصير المتوسط 0 والانحراف المعياري 1، وتستخرج المساحات من جدول التوزيع الطبيعي المعياري",1.5],["تقريباً 68% و95% و99.7% من القيم ضمن 1 و2 و3 انحرافات معيارية",1]],lab:"من إعداد المنصة (قوانين قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 5 - الدرس 3",q:"اذكر قانون فترة الثقة لمتوسط المجتمع.",m:3,kp:[["فترة الثقة = س̄ ± ز × (σ ÷ √ن)",1.5],["قيمة ز: 1.96 لمستوى ثقة 95%، و2.58 لمستوى 99%",1.5]],lab:"من إعداد المنصة (قوانين قياسية، تُراجَع على الكتاب) - ليست إجابة رسمية من الوزارة"}],philosophy:[{l:"الوحدة 1 - الموضوع 1 الفلسفة وقضايا البيئة",q:"عرّف الفلسفة البيئية، واذكر سبب ظهور المذاهب الفلسفية البيئية.",m:2,kp:[["الفلسفة البيئية فرع يعنى بدراسة البيئة ومشكلاتها",1],["هذه المشكلات نتجت عن التقدم التكنولوجي والعلمي الذي هدد البيئة الطبيعية لحياة الكائنات وعلى رأسها الإنسان",1],["ظهرت المذاهب البيئية بسبب العداء الظاهر بين الإنسان والبيئة، وتدعو إلى التوازن البيئي وإلى مركزية الطبيعة بدلاً من مركزية الإنسان واحترام حقوق الكائنات",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - الموضوع 1",q:"اشرح باختصار مذهب الأيكولوجيا العميقة عند آرني نايس.",m:4,kp:[["الأيكولوجيا العميقة مذهب تبنّاه آرني نايس",1],["تعني احترام القيمة الذاتية لكل الكائنات الحية وغير الحية",1],["تدعو إلى تغيير أيديولوجي يثمّن نوعية الحياة وتقدّر الطبيعة لذاتها",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - الموضوع 2",q:"عرّف الأخلاق التطبيقية والبيوتيقا.",m:2,kp:[["الأخلاق التطبيقية: مجموعة قواعد أخلاقية عملية تنظّم الممارسة في ميادين العلم والتكنولوجيا وما يرتبط بها من أنشطة اجتماعية واقتصادية ومهنية، وتحاول حل مشكلاتها الأخلاقية",1],["البيوتيقا (كما عرفتها جاكلين روس): علم معياري يهتم بالسلوك الإنساني المقبول في القضايا المتعلقة بالحياة والموت",1],["وتجمع دراسات تخصصات متعددة عن شروط التسيير المسؤول للحياة الإنسانية في ظل تقدم الطب والبيولوجيا",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - الموضوع 3",q:"عرّف أخلاق المهنة، وما الفرق بين الوظيفة العامة وأخلاقيات الوظيفة العامة؟",m:2,kp:[["أخلاق المهنة: المبادئ والمعايير الأخلاقية التي لا تستقيم المهنة بدونها، والإلزام فيها لا يعتمد على الضمير أو الوازع الديني فقط بل على قواعد مستنبطة من الأداء الأمثل للمهنة",1],["الوظيفة العامة: مجموعة مهام ومسؤوليات تحددها القيم والمبادئ الأخلاقية وهدفها خدمة المصلحة العامة وتنظمها قوانين الخدمة المدنية",1],["أخلاقيات الوظيفة العامة: المعايير التي يُحكم بها على السلوك بأنه صحيح أو خاطئ، والفساد الإداري ينشأ من الانحراف عنها لتحقيق مآرب شخصية",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - الموضوع 4",q:"ما المقصود بالتفلسف؟ وما علاقته بالقيم؟",m:2,kp:[["التفلسف نشاط فكري يتناول حقائق الحياة بنظرة نقدية فاحصة بدلاً من قبول الأمور على علاتها",1],["يرتبط الفكر الفلسفي بالقيم من خلال فلسفة القيم",1],["القيم الذاتية نسبية لأنها تختلف باختلاف الأفراد وأزمانهم وأماكنهم وثقافتهم",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 1 - الموضوع 4",q:"عرّف الحرية كما اصطلح عليها الفلاسفة، واذكر علاقتها بالمسؤولية.",m:2,kp:[["الحرية: اختيار الفعل عن رؤية وتفكير عميق وتدبّر",1],["مع القدرة على عدم اختياره أو اختيار ضده",1],["وجود الحرية يعني وجود المسؤولية",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 - الموضوع 1",q:"فرّق بين الاستنباط والاستقراء مع مثال لكل منهما.",m:4,kp:[["الاستنباط: استدلال لا تتجاوز نتيجته ما ورد في المقدمات، فالنتيجة مساوية لها أو أصغر، ويسير من العام إلى الخاص",1],["مثال الاستنباط: كل العزاب غير متزوجين، أيمن أعزب، إذن أيمن غير متزوج",1],["الاستقراء: استدلال تأتي نتيجته أكبر من المقدمات ويسير من الخاص إلى العام، ومثاله: الحديد والنحاس والقصدير تتمدد بالحرارة، إذن كل المعادن تتمدد بالحرارة",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"الوحدة 2 - الموضوع 1",q:"اشرح طريقة التلازم في التغير (التغير النسبي) في المنهج الاستقرائي.",m:4,kp:[["إذا تغيرت ظاهرة على نحو ما وصاحبها تغير في ظاهرة أخرى فأحدهما علة للأخرى أو معلول لها أو مرتبط بها ارتباطاً علياً",1],["تقوم الطريقة على أن أي تغير في العلة يقابله تغير في المعلول",1],["كلما تغيرت العلة تغير المعلول بطريقة طردية",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],french:[{l:"Unité 1 - Le Club des sportifs",q:"Écris 3 phrases pour dire quel sport tu fais et proposer une activité à un ami.",m:4,kp:[["Je fais du/de la + sport (ex. Je fais du football)",1],["Une proposition : On joue au tennis ? / Tu veux faire du sport avec moi ?",1],["Une réponse possible : Oui, d'accord ! / Non, je ne peux pas.",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unité 1",q:"Mets les phrases à l'impératif : tu (parler), nous (finir), vous (attendre).",m:4,kp:[["Parle (pas de s pour les verbes en -er à la 2e personne du singulier)",1],["Finissons",1],["Attendez",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unité 2 - Le Club des gourmands",q:"Tu es au supermarché. Écris un petit dialogue pour acheter des fruits et une boisson (quantités).",m:4,kp:[["Une formule polie : Bonjour, je voudrais...",1],["Des quantités correctes : un kilo de pommes, une bouteille d'eau, 500 grammes de...",1],["Le prix et la fin : Ça fait combien ? / Merci, au revoir.",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unité 2",q:"Complète avec l'article partitif : Je mange ... pain et je bois ... eau. Explique la règle.",m:3,kp:[["du pain",1],["de l'eau",1],["On utilise du / de la / de l' / des pour une quantité non précise ; après une négation on emploie de/d' (Je ne mange pas de pain)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unité 3 - Le Club des explorateurs",q:"Raconte au passé composé : hier, tu as visité une ferme (3 phrases).",m:4,kp:[["Auxiliaire avoir + participe passé : J'ai visité la ferme",1],["Une autre action correcte : J'ai vu des vaches / J'ai mangé...",1],["Bon accord et logique du récit (hier, ensuite, après)",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unité 3",q:"Mets à la forme négative : Je sais nager. Il aime les animaux.",m:4,kp:[["Je ne sais pas nager",1],["Il n'aime pas les animaux (ne devient n' devant une voyelle)",1],["La négation entoure le verbe : ne ... pas",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unité 4 - Le Club des voyageurs",q:"Écris 3 phrases pour dire où tu vas et comment tu y vas.",m:4,kp:[["Je vais à + lieu (Je vais à la gare / au marché)",1],["Le moyen de transport : en bus, en train, à pied, en voiture",1],["Phrases correctes et complètes",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Unité 4",q:"Tu as mal quelque part. Explique à un médecin (3 phrases).",m:3,kp:[["J'ai mal à la tête / au ventre / aux dents (à + partie du corps)",1],["Une sensation : J'ai chaud / J'ai froid / Je suis fatigué",1],["Une phrase polie avec le passé : Ça a commencé hier.",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}],german:[{l:"Lektion 10 - Gesundheit",q:"Schreiben Sie 3 Sätze: Was tut Ihnen weh? Beim Arzt.",m:4,kp:[["Mein Kopf / Rücken / Bauch tut weh (Singular: tut weh)",1],["Meine Augen / Ohren / Füße tun weh (Plural: tun weh)",1],["Ein höflicher Satz: Ich habe Fieber. / Ich brauche einen Termin.",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Lektion 10",q:"Geben Sie Ratschläge mit „sollen“: Sie haben Kopfschmerzen.",m:4,kp:[["Sie sollen viel Wasser trinken",1],["Du sollst ... / Ihr sollt ... mit richtiger Form des Modalverbs",1],["Der Infinitiv steht am Satzende",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Lektion 11 - In der Stadt unterwegs",q:"Fragen Sie nach dem Weg zum Bahnhof und beschreiben Sie den Weg (3 Sätze).",m:3,kp:[["Entschuldigung, wie komme ich zum Bahnhof?",1],["Gehen Sie geradeaus / links / rechts",1],["An der Ampel / Kreuzung ... Dann sind Sie da.",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Lektion 11",q:"Ergänzen Sie die Präposition: Ich fahre ... Bus. Ich gehe ... Bahnhof. Ich bin ... Schule.",m:3,kp:[["mit dem Bus",1],["zum Bahnhof (zu + dem)",1],["in der Schule oder zu Hause, mit richtigem Dativ",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Lektion 12 - Der Kunde ist König",q:"Schreiben Sie ein kurzes Gespräch im Geschäft: Sie möchten ein Produkt kaufen.",m:4,kp:[["Begrüßung: Guten Tag, ich möchte ...",1],["Frage nach Größe/Preis: Was kostet das? / Haben Sie das in Größe M?",1],["Entscheidung und Abschied: Ich nehme es. / Danke, auf Wiedersehen.",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Lektion 13 - Neue Kleider",q:"Beschreiben Sie Ihre Kleidung heute (3 Sätze) mit Farben.",m:4,kp:[["Ich trage eine blaue Hose / ein weißes Hemd",1],["Adjektivendungen richtig (eine blaue Hose, ein weißes Hemd)",1],["Eine Meinung: Das gefällt mir. / Die Jacke passt mir gut.",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Lektion 13",q:"Bilden Sie Sätze im Dativ mit „gefallen“ oder „passen“.",m:3,kp:[["Die Jacke gefällt mir",1],["Die Schuhe passen ihm nicht",1],["Personalpronomen im Dativ: mir, dir, ihm, ihr, uns, euch, ihnen",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"},{l:"Lektion 14 - Feste",q:"Laden Sie einen Freund zu einem Fest ein (3 Sätze).",m:4,kp:[["Ich lade dich zu meinem Geburtstag ein",1],["Datum, Uhrzeit, Ort: am Samstag um 18 Uhr bei mir",1],["Bitte um Antwort: Kommst du? / Gratulation und Wunsch: Alles Gute!",1]],lab:"من إعداد المنصة (من الكتاب) - ليست إجابة رسمية من الوزارة"}]};export{e as ESSAY};
